// ========================================================================
// Row-Level Security helpers
// ========================================================================
static std::string toLowerUtf8(const std::string& s);

static bool shouldEnforceRLS(const TableSchema& tbl, const std::string& user) {
    if (!tbl.rowLevelSecurity) return false;
    if (tbl.forceRowLevelSecurity || user.empty()) return true;

    // RLS bypass is a role attribute, not a username convention. Unknown
    // identities fail closed; authenticated superusers and BYPASSRLS roles
    // bypass ordinary RLS, while FORCE ROW LEVEL SECURITY still applies it.
    const auto account = authCatalog().getAuthIdByName(user);
    if (!account) return true;

    // PostgreSQL table owners bypass ordinary RLS. FORCE ROW LEVEL SECURITY
    // is handled above and deliberately applies policies to the owner too.
    // Require an existing role before comparing names; an arbitrary or
    // unauthenticated identity must never become an owner bypass.
    if (!tbl.owner.empty() && tbl.owner == account->rolname) return false;

    return !(account->rolsuper || account->rolbypassrls);
}

static bool evaluateRlsPolicies(
    const std::vector<StorageEngine::RowPolicy>& policies,
    bool withCheck,
    const std::map<std::string, std::string>& values,
    const std::map<std::string, std::string>& typeHints,
    const std::string& dbname,
    const std::string& user,
    bool& evaluationError) {
    bool hasPermissive = false;
    bool permissivePassed = false;

    for (const auto& policy : policies) {
        std::string expression = withCheck ? policy.withCheckExpr : policy.usingExpr;
        // PostgreSQL uses USING as the default WITH CHECK expression for
        // ALL and UPDATE policies when WITH CHECK is omitted.
        if (withCheck && expression.empty()) {
            const std::string command = toLowerUtf8(policy.cmd);
            if (command == "all" || command == "update") {
                expression = policy.usingExpr;
            }
        }

        bool passed = true;
        if (!expression.empty()) {
            std::string error;
            passed = ExprHelper::evalBool(expression, values, typeHints, &error,
                                          dbname, user);
            if (!error.empty()) {
                evaluationError = true;
                return false;
            }
        }

        if (policy.permissive) {
            hasPermissive = true;
            permissivePassed = permissivePassed || passed;
        } else if (!passed) {
            // Every applicable restrictive policy must accept the row.
            return false;
        }
    }

    // A set containing only restrictive policies is still default-deny: a
    // permissive policy must establish the positive access set first.
    return hasPermissive && permissivePassed;
}

static bool rowPassesRLS(const StorageEngine* engine,
                         const std::string& dbname,
                         const std::string& tablename,
                         const TableSchema& tbl,
                         const std::string& command,
                         const std::map<std::string, std::string>& values,
                         const std::map<std::string, std::string>& typeHints,
                         bool withCheck) {
    if (!engine) return false;
    const std::string user = StorageEngine::getRLSUser();
    if (!shouldEnforceRLS(tbl, user)) return true;
    const auto policies = engine->getApplicablePolicies(dbname, tablename, command, user);
    if (policies.empty()) return false;

    bool evaluationError = false;
    return evaluateRlsPolicies(policies, withCheck, values, typeHints,
                               dbname, user, evaluationError) &&
           !evaluationError;
}

// ========================================================================
// Unicode string helpers
// ========================================================================
static std::string toUpperUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towupper(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

static std::string toLowerUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towlower(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

bool StorageEngine::ReadView::isVisible(uint64_t rowTxnId) const {
    if (rowTxnId == 0) return true;              // non-transactional rows always visible
    if (rowTxnId == creatorTxnId) return true;   // inserted by current transaction
    // Prepared transactions are retained in the active xid set across a
    // process restart. Check that set before age-based snapshot shortcuts:
    // a prepared xid may be numerically older than this snapshot's xmin but
    // must remain invisible until COMMIT PREPARED.
    if (activeTxnIds.count(rowTxnId)) return false;
    if (subTxnIds.count(rowTxnId)) return false;
    if (rowTxnId < upLimitId) return true;       // all older xids committed
    if (rowTxnId >= lowLimitId) return false;    // all newer xids not started

    // For xids in [upLimitId, lowLimitId) that are no longer active,
    // consult CLOG to distinguish committed vs aborted.
    if (commitLog) {
        auto status = commitLog->getStatus(static_cast<TxnId>(rowTxnId));
        if (status == CommitLog::Status::Committed) return true;
        // ABORTED, SUB_COMMITTED, and an unflushed IN_PROGRESS status are all
        // non-visible. Never infer a commit from a missing/unfinished CLOG
        // entry: doing so leaks uncommitted rows across snapshots.
        return false;
    }

    // Fallback: assume committed for xids that left the active set
    return true;
}

// Visibility using the current PostgreSQL-style HeapTupleHeader.
bool StorageEngine::ReadView::isVisible(const char* rowBuffer, size_t len, uint32_t formatVersion) const {
    if (len == 0) return false;
    if (!usesHeapTupleHeader(formatVersion)) return false;

    if (len < sizeof(HeapTupleHeaderData)) return false;
    const auto* htup = castHeapHeader(rowBuffer);

    uint64_t xmin = htup->t_fields.t_xmin;
    uint64_t xmax = htup->t_fields.t_xmax;

    // Use hint bits when available
    bool xminComm = xminCommitted(htup);
    bool xminInv = xminInvalid(htup);
    bool xmaxComm = xmaxCommitted(htup);
    bool xmaxInv = xmaxInvalid(htup);

    // --- xmin visibility ---
    bool xminVisible = false;
    if (xmin == 0 || xminComm) {
        xminVisible = true;
    } else if (xminInv) {
        xminVisible = false;
    } else if (xmin == creatorTxnId) {
        xminVisible = true;
    } else if (activeTxnIds.count(xmin)) {
        xminVisible = false; // transaction is still in progress
    } else if (subTxnIds.count(xmin)) {
        xminVisible = false; // subtransaction in progress
    } else if (xmin < upLimitId) {
        xminVisible = true;
    } else if (xmin >= lowLimitId) {
        xminVisible = false;
    } else if (commitLog) {
        auto s = commitLog->getStatus(static_cast<TxnId>(xmin));
        xminVisible = (s == CommitLog::Status::Committed);
    } else {
        xminVisible = true; // fallback
    }

    if (!xminVisible) return false;

    // --- xmax (deletion/lock) visibility ---
    if (xmax == 0 || xmaxInv) return true; // not deleted
    if (xmaxIsLock(htup)) return true;     // xmax is only a lock, not deletion

    bool xmaxVisible = false; // true means row is still visible (delete not committed)
    if (xmax == creatorTxnId) {
        xmaxVisible = false; // current tx deleted it
    } else if (activeTxnIds.count(xmax) || subTxnIds.count(xmax)) {
        xmaxVisible = true; // prepared/in-progress delete is not committed
    } else if (xmaxComm) {
        xmaxVisible = false;
    } else if (xmax < upLimitId) {
        xmaxVisible = false;
    } else if (xmax >= lowLimitId) {
        xmaxVisible = true;
    } else if (activeTxnIds.count(xmax)) {
        xmaxVisible = true;
    } else if (commitLog) {
        auto s = commitLog->getStatus(static_cast<TxnId>(xmax));
        xmaxVisible = (s != CommitLog::Status::Committed);
    } else {
        xmaxVisible = true;
    }

    return xmaxVisible;
}

static std::string trim(const std::string& s) {
    size_t a = 0;
    while (a < s.size() && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
    size_t b = s.size();
    while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
    return s.substr(a, b - a);
}

// Build a column-name -> data-type map from a TableSchema for expression eval.
static std::map<std::string, std::string> buildTypeHints(const dbms::TableSchema& tbl) {
    std::map<std::string, std::string> hints;
    for (size_t i = 0; i < tbl.len; ++i) {
        hints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
    }
    return hints;
}

// Evaluate a SQL expression string against a row value map using ExprHelper.
static std::string evalExpressionSql(
    const std::string& exprSql,
    const std::map<std::string, std::string>& row,
    const std::map<std::string, std::string>& typeHints,
    const std::string& currentDB,
    bool* ok = nullptr) {
    if (exprSql.empty()) {
        if (ok) *ok = false;
        return "";
    }
    auto res = dbms::ExprHelper::evalString(exprSql, row, typeHints, currentDB);
    if (!res.ok) {
        if (ok) *ok = false;
        return "";
    }
    if (ok) *ok = true;
    return res.isNull ? "" : res.value;
}

static bool likeMatch(const std::string& text, const std::string& pattern) {
    std::string t = text;
    std::string p = pattern;
    for (char& c : t) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    for (char& c : p) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    size_t i = 0, j = 0;
    size_t starIdx = std::string::npos, matchIdx = 0;
    while (i < t.size()) {
        if (j < p.size() && (p[j] == t[i] || p[j] == '_')) {
            ++i; ++j;
        } else if (j < p.size() && p[j] == '%') {
            starIdx = j++;
            matchIdx = i;
        } else if (starIdx != std::string::npos) {
            j = starIdx + 1;
            i = ++matchIdx;
        } else {
            return false;
        }
    }
    while (j < p.size() && p[j] == '%') ++j;
    return j == p.size();
}

// REGEXP pattern matching (ECMAScript syntax), case-insensitive
static bool regexMatch(const std::string& text, const std::string& pattern) {
    try {
        std::regex re(pattern, std::regex::icase | std::regex::ECMAScript);
        return std::regex_search(text, re);
    } catch (...) {
        return false;
    }
}

// ========================================================================
// Helper: fixed-length string IO for the current binary catalog format.
// ========================================================================
static void writeFixedString(std::ostream& out, const std::string& s, size_t len) {
    std::string buf = s;
    buf.resize(len, '\0');
    out.write(buf.data(), static_cast<std::streamsize>(len));
}

static std::string readFixedString(std::istream& in, size_t len) {
    std::string buf(len, '\0');
    in.read(buf.data(), static_cast<std::streamsize>(len));
    auto pos = buf.find('\0');
    if (pos != std::string::npos) buf.resize(pos);
    return buf;
}

static bool validStoredIdentifier(const std::string& value, size_t fieldSize) {
    return value.find('\0') == std::string::npos && value.size() < fieldSize &&
           value.find('/') == std::string::npos &&
           value.find('\\') == std::string::npos &&
           value != "." && value != "..";
}

// Auxiliary object definitions are stored in line-oriented sidecars.  Keep
// their object names safe both as path components and as metadata fields; a
// delimiter or newline here would make the definition ambiguous on reload.
static bool validMetadataObjectName(const std::string& value) {
    if (value.empty() || !validStoredIdentifier(value, MAX_TABLE_NAME_LEN)) {
        return false;
    }
    for (char c : value) {
        if (c == '|' || c == ':' || c == ',' || c == '\n' || c == '\r') {
            return false;
        }
    }
    return true;
}

static bool ensureMetadataDirectory(const std::filesystem::path& path) {
    std::error_code error;
    if (std::filesystem::exists(path, error)) {
        return !error && std::filesystem::is_directory(path, error) && !error;
    }
    if (!std::filesystem::create_directories(path, error) && error) return false;
    return std::filesystem::is_directory(path, error) && !error;
}

static DBStatus persistMetadata(const std::filesystem::path& path,
                                const std::string& contents) {
    return index_file::writeAtomically(path, contents) ? DBStatus::OK : DBStatus::IO_ERROR;
}

static bool validateTableSchemaIdentifiers(const TableSchema& tbl, std::string* error) {
    auto reject = [&](const std::string& value, size_t fieldSize, const char* kind) {
        if (validStoredIdentifier(value, fieldSize)) return false;
        if (error) *error = std::string(kind) + " exceeds the current 63-byte identifier limit";
        return true;
    };
    if (reject(tbl.tablename, MAX_TABLE_NAME_LEN, "table name")) return false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (reject(tbl.cols[i].dataName, MAX_COL_NAME_LEN, "column name") ||
            reject(tbl.cols[i].dataType, MAX_TYPE_NAME_LEN, "type name") ||
            reject(tbl.cols[i].checkConstraintName, MAX_COL_NAME_LEN, "constraint name")) {
            return false;
        }
    }
    for (const auto& name : tbl.uniqueConstraintNames) {
        if (reject(name, MAX_TABLE_NAME_LEN, "constraint name")) return false;
    }
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        if (reject(tbl.fks[i].name, MAX_TABLE_NAME_LEN, "constraint name") ||
            reject(tbl.fks[i].refTable, MAX_TABLE_NAME_LEN, "table name")) {
            return false;
        }
        for (const auto& name : tbl.fks[i].colNames) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
        for (const auto& name : tbl.fks[i].refCols) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
    }
    return true;
}

// ========================================================================
// Column / TableSchema
// ========================================================================
void Column::print() const {
    std::cout << "ColumnName: " << dataName << '\n';
    std::cout << "hasNull: " << isNull << '\n';
    std::cout << "PrimaryKey: " << isPrimaryKey << '\n';
    std::cout << "DataType: " << dataType << '\n';
    std::cout << "DataSize: " << dsize << "\n\n";
}

void TableSchema::append(const Column& ncol) {
    if (len < MAX_COLUMNS) {
        cols[len++] = ncol;
    }
}

void TableSchema::appendFK(const ForeignKey& fk) {
    if (fkLen < MAX_COLUMNS) {
        fks[fkLen++] = fk;
    }
}

void TableSchema::print() const {
    std::cout << tablename << "\n\n";
    for (size_t i = 0; i < len; ++i) cols[i].print();
    if (fkLen > 0) {
        std::cout << "Foreign Keys:\n";
        for (size_t i = 0; i < fkLen; ++i) {
            std::cout << "  ";
            for (size_t ci = 0; ci < fks[i].colNames.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].colNames[ci];
            }
            std::cout << " -> " << fks[i].refTable << "(";
            for (size_t ci = 0; ci < fks[i].refCols.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].refCols[ci];
            }
            std::cout << ") ON DELETE " << fks[i].onDelete;
            if (!fks[i].onUpdate.empty() && fks[i].onUpdate != "restrict")
                std::cout << " ON UPDATE " << fks[i].onUpdate;
            std::cout << "\n";
        }
    }
}

size_t TableSchema::rowSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) total += cols[i].dsize;
    return total + rowHeaderSize(formatVersion, len);
}

bool TableSchema::hasVariableLength() const {
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) return true;
    }
    return false;
}

size_t TableSchema::fixedDataSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!cols[i].isVariableLength) total += cols[i].dsize;
    }
    return total;
}

size_t TableSchema::varColCount() const {
    size_t count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) ++count;
    }
    return count;
}

size_t TableSchema::getVarColIndex(size_t colIdx) const {
    size_t idx = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (cols[i].isVariableLength) ++idx;
    }
    return idx;
}

size_t TableSchema::getFixedColOffset(size_t colIdx) const {
    size_t off = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (!cols[i].isVariableLength) off += cols[i].dsize;
    }
    return off;
}

