// ========================================================================
// StorageEngine
// ========================================================================
StorageEngine::StorageEngine()
    : lockManager_(LockManager::global()) {
    if (!recoverAllDatabases()) {
        throw std::runtime_error(
            "WAL crash recovery failed; startup aborted to protect data");
    }
    cleanupStaleSessionTemporaryFiles();
    catalogService_ = std::make_unique<CatalogService>(*this);
    for (const auto& dbname : getDatabaseNames()) {
        if (!loadRuntimeStats(dbname, dbPath(dbname) / ".runtime_stats")) {
            throw std::runtime_error(
                "runtime statistics are corrupt or cannot be locked for database " + dbname);
        }
        if (!loadSqlStats(dbname, dbPath(dbname) / ".sql_stats")) {
            throw std::runtime_error(
                "SQL statistics are corrupt or cannot be locked for database " + dbname);
        }
    }
    // Keep trigger WHEN semantics available for direct StorageEngine users
    // (unit tests and embedded callers) as well as the interactive frontend.
    // main.cpp installs a richer session-aware evaluator at startup, but the
    // engine must not silently treat every WHEN clause as true when that
    // callback has not been registered yet.
    setWhenConditionEvaluator(
        [](const std::string& condition,
           const std::map<std::string, std::string>& newValues,
           const std::map<std::string, std::string>& oldValues) -> bool {
            std::map<std::string, std::string> values = oldValues;
            values.insert(newValues.begin(), newValues.end());
            std::string error;
            return ExprHelper::evalBool(condition, values, {}, &error);
        });
    lastBackgroundCheckpoint_ = std::chrono::steady_clock::now();
    startBackgroundWorker();
}

StorageEngine::TransactionContext& StorageEngine::transactionContext() const {
    const std::thread::id worker = std::this_thread::get_id();
    std::lock_guard<std::mutex> lock(transactionContextsMutex_);
    auto& context = transactionContexts_[worker];
    if (!context) context = std::make_unique<TransactionContext>();
    return *context;
}

void StorageEngine::endBackendSession() {
    const std::thread::id worker = std::this_thread::get_id();
    if (transactionContext().inTransaction) {
        rollbackTransaction();
    }
    std::lock_guard<std::mutex> lock(transactionContextsMutex_);
    transactionContexts_.erase(worker);
}

StorageEngine::~StorageEngine() {
    stopBackgroundWorker();

    // Persist deferred sequence counters before any teardown; rows inserted
    // outside an explicit transaction never pass a commit boundary.
    flushDeferredSequences();

    // Flush loaded heaps and indexes through the same WAL-aware path used by
    // transaction commit. This closes the crash window where an engine is
    // destroyed with an active transaction: recovery can apply the
    // before-image for uncommitted index changes instead of inheriting a file
    // written directly by a B+Tree/Hash destructor.
    if (catalogService_ && !catalogService_->persistAll()) {
        std::cerr << "[storage] failed to persist catalog during engine shutdown" << std::endl;
    }
    for (const auto& dbname : getDatabaseNames()) {
        if (!persistRuntimeStats(dbname, dbPath(dbname) / ".runtime_stats")) {
            std::cerr << "[storage] failed to persist runtime statistics for database "
                      << dbname << " during engine shutdown" << std::endl;
        }
        if (!persistSqlStats(dbname, dbPath(dbname) / ".sql_stats")) {
            std::cerr << "[storage] failed to persist SQL statistics for database "
                      << dbname << " during engine shutdown" << std::endl;
        }
        if (!flushDatabaseCaches(dbname)) {
            std::cerr << "[storage] failed to flush caches for database " << dbname
                      << " during engine shutdown" << std::endl;
        }
        if (auto* wal = getWAL(dbname)) {
            if (!wal->XLogFlush(wal->currentWriteLsn())) {
                std::cerr << "[storage] failed to flush WAL for database " << dbname
                          << " during engine shutdown" << std::endl;
            }
        }
    }

    // A process crash normally ends the whole process, but tests and embedded
    // callers can destroy an engine and construct another one in the same
    // process. Do not leave this engine's abandoned xids in the process-wide
    // active-transaction registry; recovery will still classify their WAL as
    // uncommitted in the next engine instance.
    std::vector<uint64_t> abandonedXids;
    {
        std::lock_guard<std::mutex> lock(transactionContextsMutex_);
        for (const auto& [worker, context] : transactionContexts_) {
            (void)worker;
            if (context && context->inTransaction && context->currentTxnId != 0) {
                abandonedXids.push_back(context->currentTxnId);
            }
        }
        transactionContexts_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        for (uint64_t xid : abandonedXids) {
            activeTransactions_.erase(xid);
            activeTransactionDatabases_.erase(xid);
        }
    }
    if (!abandonedXids.empty()) {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        for (uint64_t xid : abandonedXids) {
            ssiReadSets_.erase(xid);
            ssiWriteSets_.erase(xid);
            ssiReadRelations_.erase(xid);
            ssiWriteRelations_.erase(xid);
            ssiReadPages_.erase(xid);
            ssiWritePages_.erase(xid);
            ssiReadIndexPredicates_.erase(xid);
            ssiWriteIndexKeys_.erase(xid);
            ssiOutEdges_.erase(xid);
            ssiInEdges_.erase(xid);
            for (auto& entry : ssiInEdges_) entry.second.erase(xid);
            for (auto& entry : ssiOutEdges_) entry.second.erase(xid);
        }
    }
}

// ========================================================================
// Background workers (walwriter / bgwriter / checkpointer)
// ========================================================================

void StorageEngine::setBackgroundIntervals(uint32_t loopDelayMs,
                                           uint32_t checkpointIntervalMs) {
    std::lock_guard<std::mutex> lock(backgroundMutex_);
    backgroundLoopDelayMs_ = loopDelayMs;
    backgroundCheckpointIntervalMs_ = checkpointIntervalMs;
}

void StorageEngine::wakeBackgroundWorker() {
    backgroundCv_.notify_one();
}

void StorageEngine::startBackgroundWorker() {
    std::lock_guard<std::mutex> lock(backgroundMutex_);
    if (backgroundThread_.joinable()) return;
    backgroundStop_ = false;
    backgroundThread_ = std::thread(&StorageEngine::backgroundWorkerLoop, this);
}

void StorageEngine::stopBackgroundWorker() {
    {
        std::lock_guard<std::mutex> lock(backgroundMutex_);
        backgroundStop_ = true;
    }
    backgroundCv_.notify_all();
    if (backgroundThread_.joinable()) {
        backgroundThread_.join();
    }
}

void StorageEngine::backgroundWorkerLoop() {
    while (true) {
        std::unique_lock<std::mutex> lock(backgroundMutex_);
        auto delay = std::chrono::milliseconds(backgroundLoopDelayMs_);
        backgroundCv_.wait_for(lock, delay, [this] { return backgroundStop_.load(); });
        if (backgroundStop_.load()) break;
        lock.unlock();

        backgroundWalFlush();
        backgroundBufferFlush();
        backgroundCheckpoint();
    }
}

void StorageEngine::backgroundWalFlush() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    pruneMissingDatabaseCaches();
    // walwriter: fsync all WAL managers up to their current write LSN.
    for (auto& kv : walManagers_) {
        WALManager* wal = kv.second.get();
        if (wal) {
            if (!wal->XLogFlush(wal->currentWriteLsn())) {
                std::cerr << "[background] WAL flush failed for " << kv.first << std::endl;
            }
        }
    }
}

void StorageEngine::backgroundBufferFlush() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    // bgwriter: write out dirty pages from each buffer pool.
    for (auto& kv : pageAllocators_) {
        PageAllocator* pa = kv.second.get();
        if (pa && pa->bufferPool()) {
            pa->bufferPool()->flush();
        }
    }
}

void StorageEngine::backgroundCheckpoint() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        now - lastBackgroundCheckpoint_).count();
    if (elapsed < static_cast<int64_t>(backgroundCheckpointIntervalMs_)) {
        return;
    }
    lastBackgroundCheckpoint_ = now;

    // checkpointer: run checkpoint for every known database.
    auto dbs = getDatabaseNames();
    for (const auto& dbname : dbs) {
        checkpoint(dbname);
    }
}

