// Transaction logging helpers
// ========================================================================

bool StorageEngine::ssiIndexPredicateMatches(const SsiIndexPredicate& predicate,
                                             const SsiIndexKey& key) {
    if (predicate.dbname != key.dbname || predicate.tablename != key.tablename ||
        predicate.indexName != key.indexName) {
        return false;
    }
    const std::string lhs = BPTree::normalizeKeyForComparison(key.value);
    const std::string rhs = BPTree::normalizeKeyForComparison(predicate.value);
    if (predicate.op == "=") return lhs == rhs;
    if (predicate.op == ">") return lhs > rhs;
    if (predicate.op == ">=") return lhs >= rhs;
    if (predicate.op == "<") return lhs < rhs;
    if (predicate.op == "<=") return lhs <= rhs;
    return false;
}

void StorageEngine::recordSsiIndexPredicate(const std::string& dbname,
                                            const std::string& tablename,
                                            const Condition& condition,
                                            const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE ||
        (condition.op != "=" && condition.op != ">" && condition.op != ">=" &&
         condition.op != "<" && condition.op != "<=")) {
        return;
    }

    size_t columnIndex = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == condition.colName) {
            columnIndex = i;
            break;
        }
    }
    if (columnIndex >= tbl.len ||
        (!tbl.cols[columnIndex].collation.empty() &&
         !collation::isBinary(tbl.cols[columnIndex].collation))) {
        return;
    }

    std::vector<std::string> indexNames;
    if (tbl.pkColIndices.size() == 1 && tbl.pkColIndices.front() == columnIndex) {
        indexNames.push_back("pk:" + condition.colName);
    }
    if (getSecondaryIndex(dbname, tablename, condition.colName)) {
        indexNames.push_back("idx:" + condition.colName);
    }
    if (indexNames.empty() || condition.value.empty()) return;

    const SsiIndexPredicate predicateBase{
        dbname, tablename, "", condition.op, condition.value};
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& indexName : indexNames) {
        SsiIndexPredicate predicate = predicateBase;
        predicate.indexName = indexName;
        transactionContext().txnReadIndexPredicates.insert(predicate);
        ssiReadIndexPredicates_[transactionContext().currentTxnId].insert(std::move(predicate));
    }
}

void StorageEngine::recordSsiIndexKeys(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& rowData,
                                       const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE) {
        return;
    }

    std::vector<std::pair<std::string, std::string>> keys;
    if (tbl.pkColIndices.size() == 1) {
        const size_t columnIndex = tbl.pkColIndices.front();
        if (columnIndex < tbl.len) {
            const std::string value = extractColumnValueStatic(rowData, tbl, columnIndex);
            if (!value.empty()) {
                keys.emplace_back("pk:" + tbl.cols[columnIndex].dataName, value);
            }
        }
    }
    for (const auto& columnName : getIndexedColumns(dbname, tablename)) {
        BPTree* index = getSecondaryIndex(dbname, tablename, columnName);
        if (!index) continue;
        size_t columnIndex = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == columnName) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= tbl.len) continue;
        const std::string value = extractColumnValueStatic(rowData, tbl, columnIndex);
        if (!value.empty()) keys.emplace_back("idx:" + columnName, value);
    }

    if (keys.empty()) return;
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& [indexName, value] : keys) {
        SsiIndexKey key{dbname, tablename, indexName, value};
        transactionContext().txnWrittenIndexKeys.insert(key);
        ssiWriteIndexKeys_[transactionContext().currentTxnId].insert(std::move(key));
    }
}

void StorageEngine::logTxnInsert(const std::string& tableName, int64_t rowIdx) {
    transactionContext().txnLog.push_back({TxnLogEntry::Op::Insert, tableName, rowIdx, ""});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        std::string row;
        if (readRowByRid(getPageAllocator(transactionContext().txnDB, tableName), rowIdx, row, tbl)) {
            recordSsiIndexKeys(transactionContext().txnDB, tableName, row, tbl);
        }
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        decodeRid(rowIdx, pageId, slotId);
        std::string page = ssiPageKey(transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

void StorageEngine::logTxnUpdate(const std::string& tableName, int64_t rowIdx,
                                  const std::string& oldRowData) {
    transactionContext().txnLog.push_back({TxnLogEntry::Op::Update, tableName, rowIdx, oldRowData});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(transactionContext().txnDB, tableName, oldRowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        decodeRid(rowIdx, pageId, slotId);
        std::string page = ssiPageKey(transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

void StorageEngine::logTxnDelete(const std::string& tableName, int64_t rowIdx,
                                  const std::string& oldRowData) {
    transactionContext().txnLog.push_back({TxnLogEntry::Op::Delete, tableName, rowIdx, oldRowData});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(transactionContext().txnDB, tableName, oldRowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        decodeRid(rowIdx, pageId, slotId);
        std::string page = ssiPageKey(transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

// ========================================================================
// Transaction support (row undo log with opt-in DDL snapshots)
// ========================================================================

static void applySessionTempTableCommitActions(StorageEngine& engine,
                                               Session& session,
                                               const std::string& dbname) {
    std::vector<std::string> names;
    names.reserve(session.tempTableOnCommit.size());
    for (const auto& entry : session.tempTableOnCommit) names.push_back(entry.first);

    for (const auto& logicalName : names) {
        if (!session.tempTables.count(logicalName)) {
            session.tempTableOnCommit.erase(logicalName);
            continue;
        }
        const auto actionIt = session.tempTableOnCommit.find(logicalName);
        if (actionIt == session.tempTableOnCommit.end()) continue;
        const std::string physicalName = tempTablePrefix(session, logicalName);
        if (actionIt->second == "delete") {
            engine.truncateTable(dbname, physicalName);
        } else if (actionIt->second == "drop") {
            engine.dropTable(dbname, physicalName);
            session.tempTables.erase(logicalName);
            session.tempTableOnCommit.erase(logicalName);
        }
    }
    session.tempTablesCreatedInTransaction.clear();
}

static void rollbackSessionTempTables(StorageEngine& engine,
                                      Session& session,
                                      const std::string& dbname) {
    const auto created = session.tempTablesCreatedInTransaction;
    for (const auto& logicalName : created) {
        engine.dropTable(dbname, tempTablePrefix(session, logicalName));
        session.tempTables.erase(logicalName);
        session.tempTableOnCommit.erase(logicalName);
    }
    session.tempTablesCreatedInTransaction.clear();
}

namespace {

std::mutex g_databaseTxnLocksMutex;
std::map<std::string, std::shared_ptr<std::shared_mutex>> g_databaseTxnLocks;

std::shared_ptr<std::shared_mutex> databaseTxnLockFor(const std::string& dbname) {
    std::lock_guard<std::mutex> guard(g_databaseTxnLocksMutex);
    auto& lock = g_databaseTxnLocks[dbname];
    if (!lock) lock = std::make_shared<std::shared_mutex>();
    return lock;
}

std::filesystem::path transactionBackupPath(const std::string& dbname, uint64_t xid) {
    return std::filesystem::path(dbname + ".txn_backup." + std::to_string(xid));
}

} // anonymous namespace

DBStatus StorageEngine::beginTransaction(const std::string& dbname) {
    return beginTransaction(dbname, false);
}

void StorageEngine::preserveTransactionBackupOnRollback(bool preserve) {
    auto& context = transactionContext();
    context.preserveBackupOnRollback = preserve;
    if (!preserve || !context.inTransaction || !context.txnBackupPath.empty()) return;

    // Legacy direct callers may opt in after BEGIN. Upgrade their shared
    // database lock before taking the snapshot; the DDL wrapper uses the
    // exclusive begin overload and therefore does not need an upgrade.
    context.databaseSharedLock.reset();
    if (!context.databaseExclusiveLock) {
        context.databaseExclusiveLock = std::make_unique<std::unique_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }
    if (!createTransactionBackup()) {
        context.preserveBackupOnRollback = false;
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock = std::make_unique<std::shared_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }
}

void StorageEngine::registerDdlUndo(std::function<bool()> action) {
    if (!action || !transactionContext().inTransaction) return;
    transactionContext().ddlUndoActions.push_back(std::move(action));
}

void StorageEngine::markTransactionBackupDirty() {
    if (!transactionContext().txnBackupPath.empty()) {
        transactionContext().transactionBackupDirty = true;
    }
}

void StorageEngine::restoreTransactionBackupBeforeRowUndo(bool enable) {
    transactionContext().restoreBackupBeforeRowUndo = enable;
}

bool StorageEngine::hasTransactionBackup() const {
    return !transactionContext().txnBackupPath.empty();
}

bool StorageEngine::transactionBackupDirty() const {
    return transactionContext().transactionBackupDirty;
}

DBStatus StorageEngine::beginTransaction(const std::string& dbname, bool ddlSnapshot) {
    if (transactionContext().inTransaction) {
        // Commit existing transaction before starting a new one.
        // This matches PostgreSQL's implicit-commit-on-DDL behavior and
        // prevents transactionContext().txnDB from pointing to a stale database.
        const DBStatus previousStatus = commitTransaction();
        if (previousStatus != DBStatus::OK) return previousStatus;
    }
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;

    auto& context = transactionContext();
    context.databaseTxnMutex = databaseTxnLockFor(dbname);
    if (ddlSnapshot) {
        context.databaseExclusiveLock = std::make_unique<std::unique_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    } else {
        context.databaseSharedLock = std::make_unique<std::shared_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }

    // CatalogManager is lazily persisted and may contain the latest DDL
    // state only in memory.  Persist it before taking the transaction
    // snapshot so a DDL rollback can safely evict/reload the catalog.
    if (catalogService_ && !catalogService_->persistAll()) {
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock.reset();
        context.databaseTxnMutex.reset();
        return DBStatus::IO_ERROR;
    }

    // Flush every loaded heap and index cache before taking the transaction
    // snapshot.  Otherwise a backup can contain older index pages than the
    // heap rows already visible through the in-memory caches.
    if (!flushDatabaseCaches(dbname)) {
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock.reset();
        context.databaseTxnMutex.reset();
        return DBStatus::IO_ERROR;
    }

    // Assign transaction ID and create ReadView (if needed).
    transactionContext().currentTxnId = TxnIdGenerator::instance().nextTxId();
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.insert(transactionContext().currentTxnId);
        activeTransactionDatabases_[transactionContext().currentTxnId] = dbname;
    }
    // Initialize SSI tracking
    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_[transactionContext().currentTxnId].clear();
        ssiWriteSets_[transactionContext().currentTxnId].clear();
        ssiReadRelations_[transactionContext().currentTxnId].clear();
        ssiWriteRelations_[transactionContext().currentTxnId].clear();
        ssiReadPages_[transactionContext().currentTxnId].clear();
        ssiWritePages_[transactionContext().currentTxnId].clear();
        ssiReadIndexPredicates_[transactionContext().currentTxnId].clear();
        ssiWriteIndexKeys_[transactionContext().currentTxnId].clear();
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();
    if (transactionContext().txnIsolationLevel != IsolationLevel::READ_UNCOMMITTED) {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        transactionContext().readView.creatorTxnId = transactionContext().currentTxnId;
        transactionContext().readView.upLimitId = activeTransactions_.empty() ? transactionContext().currentTxnId : *activeTransactions_.begin();
        transactionContext().readView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        transactionContext().readView.activeTxnIds = activeTransactions_;
        transactionContext().readView.activeTxnIds.erase(transactionContext().currentTxnId);
        transactionContext().readView.subTxnIds.clear();
        transactionContext().readView.subTxnIds.insert(transactionContext().txnSubTxnIds.begin(), transactionContext().txnSubTxnIds.end());
        transactionContext().readView.commitLog = getCommitLog(dbname);
    }

    // Capture catalog snapshot for consistent catalog view within transaction
    captureCatalogSnapshot();

    transactionContext().txnLog.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().ddlUndoActions.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().inTransaction = true;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnBackupPath.clear();
    transactionContext().txnDB = dbname;
    return DBStatus::OK;
}

bool StorageEngine::createTransactionBackup() {
    auto& context = transactionContext();
    if (!context.inTransaction || context.txnDB.empty() || context.currentTxnId == 0) {
        return false;
    }
    if (!context.txnBackupPath.empty()) return true;
    const std::string dbname = context.txnDB;
    if (catalogService_ && !catalogService_->persistAll()) return false;

    // The exclusive database lock is acquired by beginTransaction(..., true)
    // before this copy starts. This prevents a physical restore from erasing
    // another backend's committed changes.
    const auto tables = getTableNames(dbname);
    if (!flushDatabaseCaches(dbname)) return false;

    const auto backup = transactionBackupPath(dbname, context.currentTxnId);
    std::error_code ec;
    std::filesystem::remove_all(backup, ec);
    if (!physicalBackup(dbname, backup.string())) {
        std::filesystem::remove_all(backup, ec);
        return false;
    }

    // UNLOGGED relations are intentionally empty after crash recovery. Remove
    // every physical fork/index/TOAST file from the snapshot while retaining
    // their schema and catalog metadata.
    for (const auto& tn : tables) {
        TableSchema ts = getTableSchema(dbname, tn);
        if (!ts.isUnlogged) continue;
        std::filesystem::path relationBackup = backup;
        if (!ts.tablespace.empty() && ts.tablespace != "pg_default") {
            relationBackup /= "tablespaces";
            relationBackup /= ts.tablespace;
        }
        if (!std::filesystem::exists(relationBackup)) continue;
        for (const auto& entry : std::filesystem::directory_iterator(relationBackup)) {
            if (isRelationPhysicalFileName(entry.path().filename().string(), tn)) {
                std::filesystem::remove_all(entry.path(), ec);
                if (ec) {
                    std::filesystem::remove_all(backup, ec);
                    return false;
                }
            }
        }
    }
    context.txnBackupPath = backup.string();
    context.transactionBackupDirty = false;
    context.ddlUndoSizeAtBackup = context.ddlUndoActions.size();
    return true;
}

DBStatus StorageEngine::commitTransaction() {
    if (!transactionContext().inTransaction) return DBStatus::OK;
    lockManager_.setResourceNamespace(transactionContext().txnDB);

    // SSI conflict detection for Serializable isolation
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        std::unique_lock<std::mutex> lock(ssiMutex_);
        bool hasOutgoing = false, hasIncoming = false;

        for (const auto& [otherTxId, otherWriteSet] : ssiWriteSets_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& rid : transactionContext().txnReadRids) {
                if (otherWriteSet.count(rid)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherWritePages] : ssiWritePages_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& page : transactionContext().txnReadPages) {
                if (otherWritePages.count(page)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherWriteKeys] : ssiWriteIndexKeys_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& predicate : transactionContext().txnReadIndexPredicates) {
                for (const auto& key : otherWriteKeys) {
                    if (ssiIndexPredicateMatches(predicate, key)) {
                        hasOutgoing = true;
                        ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                        ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                        break;
                    }
                }
                if (hasOutgoing) break;
            }
            if (hasOutgoing) break;
        }

        // Relation-level SIREAD coverage catches empty scans and predicates
        // whose result set did not contain a row. It is the conservative
        // fallback; non-empty scans use page coverage above.
        for (const auto& [otherTxId, otherWriteRelations] : ssiWriteRelations_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& relation : transactionContext().txnReadRelations) {
                if (otherWriteRelations.count(relation)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherReadSet] : ssiReadSets_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& rid : transactionContext().txnWrittenRids) {
                if (otherReadSet.count(rid)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadPages] : ssiReadPages_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& page : transactionContext().txnWrittenPages) {
                if (otherReadPages.count(page)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadPredicates] : ssiReadIndexPredicates_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& key : transactionContext().txnWrittenIndexKeys) {
                for (const auto& predicate : otherReadPredicates) {
                    if (ssiIndexPredicateMatches(predicate, key)) {
                        hasIncoming = true;
                        ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                        ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                        break;
                    }
                }
                if (hasIncoming) break;
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadRelations] : ssiReadRelations_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& relation : transactionContext().txnWrittenRelations) {
                if (otherReadRelations.count(relation)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        if (hasOutgoing && hasIncoming) {
            // Dangerous structure detected - must abort
            uint64_t abortedId = transactionContext().currentTxnId;
            ssiReadSets_.erase(abortedId);
            ssiWriteSets_.erase(abortedId);
            ssiReadRelations_.erase(abortedId);
            ssiWriteRelations_.erase(abortedId);
            ssiReadPages_.erase(abortedId);
            ssiWritePages_.erase(abortedId);
            ssiReadIndexPredicates_.erase(abortedId);
            ssiWriteIndexKeys_.erase(abortedId);
            ssiOutEdges_.erase(abortedId);
            for (auto& [k, v] : ssiInEdges_) v.erase(abortedId);
            ssiInEdges_.erase(abortedId);
            for (auto& [k, v] : ssiOutEdges_) v.erase(abortedId);
            transactionContext().txnReadRids.clear();
            transactionContext().txnWrittenRids.clear();
            transactionContext().txnReadRelations.clear();
            transactionContext().txnWrittenRelations.clear();
            transactionContext().txnReadPages.clear();
            transactionContext().txnWrittenPages.clear();
            transactionContext().txnReadIndexPredicates.clear();
            transactionContext().txnWrittenIndexKeys.clear();
            // rollbackTransaction() performs its own SSI cleanup and must
            // acquire ssiMutex_.  Release the detection lock first to avoid
            // self-deadlocking on the serialization-failure path.
            lock.unlock();
            rollbackTransaction();
            return DBStatus::SERIALIZATION_FAILURE;
        }

        // Keep committed SSI coverage while another serializable transaction
        // is active; a later committer may need the completed transaction's
        // read/write edges to finish dangerous-structure detection.  The last
        // transaction out clears the global history below.
        transactionContext().txnReadRids.clear();
        transactionContext().txnWrittenRids.clear();
        transactionContext().txnReadRelations.clear();
        transactionContext().txnWrittenRelations.clear();
        transactionContext().txnReadPages.clear();
        transactionContext().txnWrittenPages.clear();
        transactionContext().txnReadIndexPredicates.clear();
        transactionContext().txnWrittenIndexKeys.clear();
    }

    // Run deferred CHECK constraints queued for this transaction before committing.
    {
        auto it = transactionContext().deferredChecks.find(transactionContext().currentTxnId);
        if (it != transactionContext().deferredChecks.end()) {
            for (const auto& dc : it->second) {
                if (!runDeferredCheck(dc)) {
                    rollbackTransaction();
                    return DBStatus::INVALID_VALUE;
                }
            }
            transactionContext().deferredChecks.erase(it);
        }
    }

    // A transaction is not durable until its COMMIT record is present and
    // flushed. Fail closed before publishing CLOG visibility: otherwise a
    // WAL/fsync error could expose committed rows that crash recovery cannot
    // reconstruct.
    const std::string committingDb = transactionContext().txnDB;
    const uint64_t committingTxnId = transactionContext().currentTxnId;
    // Force all loaded heap/index caches durable before publishing the COMMIT
    // record so a committed transaction cannot expose a dirty in-memory index
    // that is absent from its files.
    if (!flushDatabaseCaches(committingDb)) {
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }
    WALManager* wal = getWAL(committingDb);
    if (!wal) {
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }
    const Lsn commitLsn = walXactCommit(committingDb, committingTxnId);
    if (commitLsn == INVALID_LSN || !wal->XLogFlush(commitLsn)) {
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    // Update and durably publish CLOG before clearing transaction state. WAL
    // alone is sufficient to reconstruct status after a crash, but the live
    // backend must never report a successful commit after CLOG persistence
    // failed.
    CommitLog* clog = getCommitLog(transactionContext().txnDB);
    if (clog) {
        clog->setStatus(transactionContext().currentTxnId, CommitLog::Status::Committed);
        if (!clog->flush()) {
            rollbackTransaction();
            return DBStatus::IO_ERROR;
        }
    }

    // Old UPDATE/DELETE row versions retain TOAST markers until the commit
    // record is durable.  They are no longer reachable after COMMIT, so
    // reclaim their chunks now; a cleanup failure only leaves garbage for
    // VACUUM TOAST and cannot invalidate the committed row.
    for (const auto& entry : transactionContext().txnLog) {
        if (entry.op == TxnLogEntry::Op::Update || entry.op == TxnLogEntry::Op::Delete) {
            deleteToastForRow(committingDb, entry.tableName, entry.rowData);
        }
    }

    // Update max committed txId
    TxnIdGenerator::instance().notifyCommit(transactionContext().currentTxnId);
    // Remove from active set
    bool noActiveTransactions = false;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(transactionContext().currentTxnId);
        activeTransactionDatabases_.erase(transactionContext().currentTxnId);
        noActiveTransactions = activeTransactions_.empty();
    }
    if (noActiveTransactions) {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_.clear();
        ssiWriteSets_.clear();
        ssiReadRelations_.clear();
        ssiWriteRelations_.clear();
        ssiReadPages_.clear();
        ssiWritePages_.clear();
        ssiReadIndexPredicates_.clear();
        ssiWriteIndexKeys_.clear();
        ssiOutEdges_.clear();
        ssiInEdges_.clear();
    }
    transactionContext().txnLog.clear();
    transactionContext().ddlUndoActions.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    discardTransactionBackup(transactionContext().txnDB);
    transactionContext().savepoints.clear();
    transactionContext().txnSubTxnIds.clear();
    clearCatalogSnapshot();
    lockManager_.unlockAll();
    lockManager_.unlockAllGaps();
    if (Session* session = currentSession();
        session && session->currentDB == transactionContext().txnDB) {
        applySessionTempTableCommitActions(*this, *session, transactionContext().txnDB);
    }
    transactionContext().constraintMode.clear();
    transactionContext().deferredChecks.erase(transactionContext().currentTxnId);
    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    flushDeferredSequences();
    return DBStatus::OK;
}

DBStatus StorageEngine::rollbackTransaction() {
    if (!transactionContext().inTransaction) return DBStatus::OK;
    lockManager_.setResourceNamespace(transactionContext().txnDB);

    const std::string rollbackDb = transactionContext().txnDB;
    const bool preserveBackup = transactionContext().preserveBackupOnRollback;
    const bool hasBackup = preserveBackup &&
        transactionContext().restoreBackupBeforeRowUndo &&
        transactionContext().transactionBackupDirty &&
        !transactionContext().txnBackupPath.empty();
    const size_t ddlUndoReplaySize = hasBackup
        ? transactionContext().ddlUndoSizeAtBackup
        : transactionContext().ddlUndoActions.size();
    bool snapshotRestoreOk = true;

    // A DDL snapshot may have been taken in the middle of an explicit outer
    // transaction. Restore it before row undo so the row log can replay from
    // the same physical state captured by the snapshot. This also makes a
    // full ROLLBACK restore DROP/REPLACE operations without reintroducing the
    // rows that existed before the snapshot was taken.
    if (hasBackup) {
        snapshotRestoreOk = restoreTransactionBackup(rollbackDb);
    }

    // Mark transaction as aborted in CLOG. Continue rollback even if the
    // status cannot be persisted, but report the durability failure after all
    // in-memory and physical undo work has completed.
    bool clogOk = true;
    CommitLog* clog = getCommitLog(transactionContext().txnDB);
    if (clog) {
        clog->setStatus(transactionContext().currentTxnId, CommitLog::Status::Aborted);
        clogOk = clog->flush();
    }

    // Remove from active set (aborted, not committed)
    bool noActiveTransactions = false;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(transactionContext().currentTxnId);
        activeTransactionDatabases_.erase(transactionContext().currentTxnId);
        noActiveTransactions = activeTransactions_.empty();
    }

    // Replay txnLog in reverse order to undo changes
    for (auto it = transactionContext().txnLog.rbegin(); it != transactionContext().txnLog.rend(); ++it) {
        PageAllocator* pa = getPageAllocator(transactionContext().txnDB, it->tableName);
        TableSchema tbl = getTableSchema(transactionContext().txnDB, it->tableName);

        if (it->op == TxnLogEntry::Op::Insert) {
            // Undo INSERT: remove the row
            uint32_t pageId; uint16_t slotId;
            decodeRid(it->rowIdx, pageId, slotId);
            // Read row data before removing so index entries can be cleaned up.
            std::string insertedRow;
            std::string pkVal;
            std::map<std::string, std::string> secIdxVals;
            std::map<std::string, std::string> compositeIdxVals;
            std::map<std::string, std::string> hashIdxVals;
            {
                std::string row;
                if (readRowByRid(pa, it->rowIdx, row, tbl)) {
                    insertedRow = row;
                    pkVal = extractPKValue(row, tbl);
                    auto indexedCols = getIndexedColumns(transactionContext().txnDB, it->tableName);
                    for (const auto& colname : indexedCols) {
                        size_t colIdx = tbl.len;
                        for (size_t i = 0; i < tbl.len; ++i) {
                            if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                        }
                        if (colIdx < tbl.len) {
                            secIdxVals[colname] = extractColumnValue(row, tbl, colIdx);
                        }
                    }
                    for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, it->tableName)) {
                        std::string key = buildCompositeKey(row, tbl, ci.columns);
                        if (!key.empty()) compositeIdxVals[ci.name] = key;
                    }
                    for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, it->tableName)) {
                        size_t colIdx = tbl.len;
                        for (size_t i = 0; i < tbl.len; ++i) {
                            if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                        }
                        if (colIdx < tbl.len) {
                            std::string value = extractColumnValue(row, tbl, colIdx);
                            if (!value.empty()) hashIdxVals[colname] = value;
                        }
                    }
                }
            }
            if (!insertedRow.empty()) {
                deleteRowToast(transactionContext().txnDB, it->tableName, it->rowIdx);
            }
            char* pageBuf = pa->fetchPage(pageId);
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, it->tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                page.remove(slotId);
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, it->tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Remove from PK index
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, it->tableName);
            if (pkIdx && !pkVal.empty()) {
                pkIdx->remove(pkVal);
            }
            // Remove from secondary indexes
            for (const auto& kv : secIdxVals) {
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, it->tableName, kv.first);
                if (secIdx && !kv.second.empty()) {
                    secIdx->removeMulti(kv.second, it->rowIdx);
                }
            }
            for (const auto& kv : compositeIdxVals) {
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, it->tableName, kv.first);
                if (compositeIdx && !kv.second.empty()) {
                    compositeIdx->removeMulti(kv.second, it->rowIdx);
                }
            }
            for (const auto& kv : hashIdxVals) {
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, it->tableName, kv.first);
                if (hashIdx && !kv.second.empty()) {
                    hashIdx->remove(kv.second, it->rowIdx);
                }
            }
        } else if (it->op == TxnLogEntry::Op::Update) {
            // Undo UPDATE: restore old row data
            uint32_t pageId; uint16_t slotId;
            decodeRid(it->rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            std::string currentRow;
            bool foundCurrent = false;
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, it->tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                // Read current row data before restoring (needed to remove stale index entries)
                const char* currentData = nullptr;
                size_t currentLen = 0;
                bool got = page.read(slotId, currentData, currentLen);
                if (got && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    currentRow = stripRowHeader(currentData, currentLen, tbl.formatVersion, tbl.len);
                    foundCurrent = true;
                } else if (!got) {
                    std::string targetPk = extractPKValue(it->rowData, tbl);
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (foundCurrent || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(rowData, tbl);
                        if (pk == targetPk) {
                            currentRow = rowData;
                            foundCurrent = true;
                        }
                    });
                }
                if (foundCurrent) {
                    deleteToastForRowExcept(transactionContext().txnDB, it->tableName,
                                            currentRow, it->rowData);
                }
                // Restore old row data
                if (got && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), it->rowData, tbl.formatVersion, tbl.len);
                    setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                } else if (!got) {
                    std::string targetPk = extractPKValue(it->rowData, tbl);
                    bool restored = false;
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (restored || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(rowData, tbl);
                        if (pk == targetPk) {
                            std::string fullRow = replaceRowData(
                                std::string(data, len), it->rowData, tbl.formatVersion, tbl.len);
                            setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            page.update(sid, fullRow.data(), fullRow.size());
                            restored = true;
                        }
                    });
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, it->tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Rebuild indexes: remove current (stale) values then insert restored values
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, it->tableName);
            if (pkIdx) {
                if (foundCurrent) {
                    std::string currentPk = extractPKValue(currentRow, tbl);
                    if (!currentPk.empty()) pkIdx->remove(currentPk);
                }
                std::string pkVal = extractPKValue(it->rowData, tbl);
                if (!pkVal.empty()) pkIdx->insert(pkVal, it->rowIdx);
            }
            auto indexedCols = getIndexedColumns(transactionContext().txnDB, it->tableName);
            for (const auto& colname : indexedCols) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, it->tableName, colname);
                if (!secIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = extractColumnValue(currentRow, tbl, colIdx);
                    if (!currentVal.empty()) secIdx->removeMulti(currentVal, it->rowIdx);
                }
                std::string val = extractColumnValue(it->rowData, tbl, colIdx);
                if (!val.empty()) secIdx->insertMulti(val, it->rowIdx);
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, it->tableName)) {
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, it->tableName, ci.name);
                if (!compositeIdx) continue;
                if (foundCurrent) {
                    std::string currentKey = buildCompositeKey(currentRow, tbl, ci.columns);
                    if (!currentKey.empty()) compositeIdx->removeMulti(currentKey, it->rowIdx);
                }
                std::string oldKey = buildCompositeKey(it->rowData, tbl, ci.columns);
                if (!oldKey.empty()) compositeIdx->insertMulti(oldKey, it->rowIdx);
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, it->tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, it->tableName, colname);
                if (!hashIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = extractColumnValue(currentRow, tbl, colIdx);
                    if (!currentVal.empty()) hashIdx->remove(currentVal, it->rowIdx);
                }
                std::string oldVal = extractColumnValue(it->rowData, tbl, colIdx);
                if (!oldVal.empty()) hashIdx->insert(oldVal, it->rowIdx);
            }
        } else if (it->op == TxnLogEntry::Op::Delete) {
            // Undo DELETE: restore the row by clearing tombstone and writing back old data
            uint32_t pageId; uint16_t slotId;
            decodeRid(it->rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, it->tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                // Transactional DELETE keeps the tuple in place. Restore the
                // payload and clear xmax so a later COMMIT of the surrounding
                // transaction does not hide a row rolled back to this point.
                const char* currentData = nullptr;
                size_t currentLen = 0;
                size_t hdrLen = rowHeaderSize(tbl.formatVersion, tbl.len);
                if (page.read(slotId, currentData, currentLen) && currentLen >= hdrLen) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), it->rowData, tbl.formatVersion, tbl.len);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, it->tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Re-add to indexes
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, it->tableName);
            if (pkIdx) {
                std::string pkVal = extractPKValue(it->rowData, tbl);
                if (!pkVal.empty()) pkIdx->insert(pkVal, it->rowIdx);
            }
            auto indexedCols = getIndexedColumns(transactionContext().txnDB, it->tableName);
            for (const auto& colname : indexedCols) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, it->tableName, colname);
                if (!secIdx) continue;
                std::string val = extractColumnValue(it->rowData, tbl, colIdx);
                if (!val.empty()) secIdx->insertMulti(val, it->rowIdx);
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, it->tableName)) {
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, it->tableName, ci.name);
                if (!compositeIdx) continue;
                std::string key = buildCompositeKey(it->rowData, tbl, ci.columns);
                if (!key.empty()) compositeIdx->insertMulti(key, it->rowIdx);
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, it->tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, it->tableName, colname);
                if (!hashIdx) continue;
                std::string value = extractColumnValue(it->rowData, tbl, colIdx);
                if (!value.empty()) hashIdx->insert(value, it->rowIdx);
            }
        }
    }

    // DDL wrappers register CREATE undo actions in the outer transaction.
    // Replay them only after row undo: INSERTs into a table created in the
    // same transaction still need that table to exist while their rows are
    // being removed.
    bool ddlUndoOk = true;
    auto ddlUndoEnd = transactionContext().ddlUndoActions.rend();
    auto ddlUndoBegin = transactionContext().ddlUndoActions.rbegin();
    if (ddlUndoReplaySize < transactionContext().ddlUndoActions.size()) {
        ddlUndoBegin = transactionContext().ddlUndoActions.rbegin() +
                       (transactionContext().ddlUndoActions.size() - ddlUndoReplaySize);
    }
    for (auto it = ddlUndoBegin; it != ddlUndoEnd; ++it) {
        try {
            if (!(*it)()) ddlUndoOk = false;
        } catch (...) {
            ddlUndoOk = false;
        }
    }
    transactionContext().ddlUndoActions.clear();

    // Write WAL ABORT marker after undo.
    WALManager* wal = getWAL(transactionContext().txnDB);
    bool abortWalOk = true;
    if (wal) {
        const Lsn abortLsn = walXactAbort(transactionContext().txnDB,
                                           transactionContext().currentTxnId);
        abortWalOk = abortLsn != INVALID_LSN && wal->XLogFlush(abortLsn);
    } else {
        abortWalOk = false;
    }

    transactionContext().deferredChecks.erase(transactionContext().currentTxnId);
    transactionContext().txnLog.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().savepoints.clear();
    transactionContext().txnSubTxnIds.clear();
    clearCatalogSnapshot();
    lockManager_.unlockAll();
    lockManager_.unlockAllGaps();

    // Clean up SSI data for aborted transaction
    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        if (noActiveTransactions) {
            ssiReadSets_.clear();
            ssiWriteSets_.clear();
            ssiReadRelations_.clear();
            ssiWriteRelations_.clear();
            ssiReadPages_.clear();
            ssiWritePages_.clear();
            ssiReadIndexPredicates_.clear();
            ssiWriteIndexKeys_.clear();
            ssiOutEdges_.clear();
            ssiInEdges_.clear();
        } else {
            ssiReadSets_.erase(transactionContext().currentTxnId);
            ssiWriteSets_.erase(transactionContext().currentTxnId);
            ssiReadRelations_.erase(transactionContext().currentTxnId);
            ssiWriteRelations_.erase(transactionContext().currentTxnId);
            ssiReadPages_.erase(transactionContext().currentTxnId);
            ssiWritePages_.erase(transactionContext().currentTxnId);
            ssiReadIndexPredicates_.erase(transactionContext().currentTxnId);
            ssiWriteIndexKeys_.erase(transactionContext().currentTxnId);
            ssiOutEdges_.erase(transactionContext().currentTxnId);
            for (auto& [k, v] : ssiInEdges_) v.erase(transactionContext().currentTxnId);
            ssiInEdges_.erase(transactionContext().currentTxnId);
            for (auto& [k, v] : ssiOutEdges_) v.erase(transactionContext().currentTxnId);
        }
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();

    if (Session* session = currentSession();
        session && session->currentDB == transactionContext().txnDB) {
        rollbackSessionTempTables(*this, *session, transactionContext().txnDB);
    }

    if (!preserveBackup) discardTransactionBackup(rollbackDb);

    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    transactionContext().constraintMode.clear();
    transactionContext().deferredChecks.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    // Sequences are non-transactional: persist advanced counters even on
    // rollback so concurrent transactions cannot observe reused values.
    flushDeferredSequences();
    return snapshotRestoreOk && ddlUndoOk && clogOk && abortWalOk
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

bool StorageEngine::restoreTransactionBackup(const std::string& dbname) {
    if (dbname.empty()) return false;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto& context = transactionContext();
    std::filesystem::path backup = context.txnBackupPath;
    if (backup.empty()) {
        // No legacy snapshot format is created anymore. This fallback keeps
        // the API fail-closed for callers that have no current transaction.
        return false;
    }
    if (!std::filesystem::exists(backup) || !std::filesystem::is_directory(backup)) {
        return false;
    }

    // DDL may have changed relation files and catalog state without creating
    // row-level undo records.  Close every database-owned cache before
    // replacing the directory so no stale file handles survive the restore.
    if (catalogService_) catalogService_->evict(dbname);
    closeDatabaseCaches(dbname);
    const bool restored = physicalRestore(dbname, backup.string());
    if (restored) {
        std::error_code ec;
        std::filesystem::remove_all(backup, ec);
        context.txnBackupPath.clear();
        context.transactionBackupDirty = false;
        context.restoreBackupBeforeRowUndo = false;
        context.ddlUndoSizeAtBackup = 0;
    }
    return restored;
}

void StorageEngine::discardTransactionBackup(const std::string& dbname) {
    if (dbname.empty()) return;
    auto& context = transactionContext();
    std::error_code ec;
    if (!context.txnBackupPath.empty()) {
        std::filesystem::remove_all(context.txnBackupPath, ec);
        context.txnBackupPath.clear();
    }
    context.transactionBackupDirty = false;
    context.restoreBackupBeforeRowUndo = false;
    context.ddlUndoSizeAtBackup = 0;
}

// ========================================================================
// Two-phase commit support
// ========================================================================

static std::filesystem::path preparedDir() {
    return std::filesystem::path("info") / ".prepared";
}

static std::filesystem::path preparedPath(const std::string& xid) {
    return preparedDir() / xid;
}

static bool validPreparedXid(const std::string& xid) {
    if (xid.empty() || xid.size() > 200) return false;
    for (const unsigned char c : xid) {
        if (!(std::isalnum(c) || c == '_' || c == '-' || c == '.' || c == ':')) return false;
    }
    return true;
}

static bool writePreparedFileAtomically(const std::filesystem::path& target,
                                        const std::string& contents) {
    const auto parent = target.parent_path();
    const auto temp = target.string() + ".tmp." + std::to_string(::getpid());
    const int fd = ::open(temp.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC, 0600);
    if (fd < 0) return false;
    bool ok = true;
    size_t offset = 0;
    while (offset < contents.size()) {
        const ssize_t written = ::write(fd, contents.data() + offset,
                                        contents.size() - offset);
        if (written <= 0) { ok = false; break; }
        offset += static_cast<size_t>(written);
    }
    if (ok && ::fsync(fd) != 0) ok = false;
    if (::close(fd) != 0) ok = false;
    if (!ok) {
        std::error_code ec;
        std::filesystem::remove(temp, ec);
        return false;
    }
    std::error_code ec;
    std::filesystem::rename(temp, target, ec);
    if (ec) {
        std::filesystem::remove(temp, ec);
        return false;
    }
    const int dirFd = ::open(parent.c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (dirFd < 0) return false;
    const bool durable = ::fsync(dirFd) == 0;
    ::close(dirFd);
    return durable;
}

static bool removePreparedFileDurably(const std::filesystem::path& target) {
    std::error_code ec;
    if (std::filesystem::exists(target, ec) &&
        !std::filesystem::remove(target, ec)) return false;
    if (ec) return false;
    const int dirFd = ::open(target.parent_path().c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (dirFd < 0) return false;
    const bool durable = ::fsync(dirFd) == 0;
    ::close(dirFd);
    return durable;
}

static bool readPreparedRecord(const std::filesystem::path& path,
                               PreparedTransactionRecord& record) {
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    std::string line;
    bool hasTxnId = false;
    bool hasDbname = false;
    bool hasFormat = false;
    bool hasIsolation = false;
    while (std::getline(input, line)) {
        try {
            if (line.rfind("PREPARED_FORMAT ", 0) == 0) {
                const std::string value = line.substr(std::string("PREPARED_FORMAT ").size());
                size_t consumed = 0;
                const long long format = std::stoll(value, &consumed);
                if (hasFormat || consumed != value.size() ||
                    format != PreparedTransactionRecord::CURRENT_FORMAT) {
                    return false;
                }
                hasFormat = true;
            } else if (line.rfind("TXN_ID ", 0) == 0) {
                if (hasTxnId) return false;
                const std::string value = line.substr(7);
                size_t consumed = 0;
                record.txnId = std::stoull(value, &consumed);
                if (consumed != value.size()) return false;
                hasTxnId = true;
            } else if (line.rfind("DBNAME ", 0) == 0) {
                if (hasDbname) return false;
                record.dbname = line.substr(7);
                hasDbname = true;
            } else if (line.rfind("ISOLATION ", 0) == 0) {
                if (hasIsolation) return false;
                const int value = std::stoi(line.substr(10));
                if (value < static_cast<int>(IsolationLevel::READ_UNCOMMITTED) ||
                    value > static_cast<int>(IsolationLevel::SERIALIZABLE)) return false;
                record.isolation = static_cast<IsolationLevel>(value);
                hasIsolation = true;
            } else if (line.rfind("READONLY ", 0) == 0) {
                const std::string value = line.substr(9);
                if (value != "0" && value != "1") return false;
            } else if (line.rfind("LOCK ", 0) == 0) {
                std::istringstream lockLine(line.substr(5));
                std::string kind;
                if (!(lockLine >> kind)) return false;
                LockManager::PreparedLockInfo lock;
                std::string mode;
                std::string encodedTable;
                if (kind == "TABLE") {
                    if (!(lockLine >> mode >> encodedTable) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Table;
                } else if (kind == "ROW") {
                    std::string rid;
                    if (!(lockLine >> mode >> encodedTable >> rid) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    size_t consumed = 0;
                    lock.rid = std::stoll(rid, &consumed);
                    if (consumed != rid.size()) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Row;
                } else if (kind == "PAGE") {
                    std::string pageId;
                    if (!(lockLine >> mode >> encodedTable >> pageId) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    size_t consumed = 0;
                    const auto parsed = std::stoull(pageId, &consumed);
                    if (consumed != pageId.size() || parsed > UINT32_MAX) return false;
                    lock.pageId = static_cast<uint32_t>(parsed);
                    lock.kind = LockManager::PreparedLockInfo::Kind::Page;
                } else if (kind == "GAP") {
                    std::string encodedLeft;
                    std::string encodedRight;
                    if (!(lockLine >> encodedTable >> encodedLeft >> encodedRight) ||
                        !preparedHexDecode(encodedTable, lock.table) ||
                        !preparedHexDecode(encodedLeft, lock.leftKey) ||
                        !preparedHexDecode(encodedRight, lock.rightKey)) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Gap;
                    lock.mode = LockManager::LockMode::Exclusive;
                } else {
                    return false;
                }
                if (lockLine >> mode) return false;
                lock.dbname = record.dbname;
                record.locks.push_back(std::move(lock));
            } else if (line.rfind("LOG ", 0) == 0) {
                size_t pos = 4;
                const size_t opEnd = line.find(' ', pos);
                if (opEnd == std::string::npos) return false;
                const std::string op = line.substr(pos, opEnd - pos);
                pos = opEnd + 1;
                const size_t tableEnd = line.find(' ', pos);
                if (tableEnd == std::string::npos) return false;
                const std::string table = line.substr(pos, tableEnd - pos);
                pos = tableEnd + 1;
                const size_t ridEnd = line.find(' ', pos);
                if (ridEnd == std::string::npos) return false;
                PreparedTransactionRecord::LogEntry entry;
                if (op == "INSERT") entry.op = PreparedTransactionRecord::LogEntry::Op::Insert;
                else if (op == "UPDATE") entry.op = PreparedTransactionRecord::LogEntry::Op::Update;
                else if (op == "DELETE") entry.op = PreparedTransactionRecord::LogEntry::Op::Delete;
                else return false;
                entry.tableName = table;
                entry.rowIdx = std::stoll(line.substr(pos, ridEnd - pos));
                const std::string hex = line.substr(ridEnd + 1);
                if (hex.size() % 2 != 0) return false;
                for (size_t i = 0; i < hex.size(); i += 2) {
                    const auto nibble = [](char c) -> int {
                        if (c >= '0' && c <= '9') return c - '0';
                        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
                        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
                        return -1;
                    };
                    const int high = nibble(hex[i]);
                    const int low = nibble(hex[i + 1]);
                    if (high < 0 || low < 0) return false;
                    entry.rowData.push_back(static_cast<char>((high << 4) | low));
                }
                record.log.push_back(std::move(entry));
            } else if (!line.empty()) {
                return false;
            }
        } catch (...) {
            return false;
        }
    }
    if (!input.eof()) return false;
    return hasFormat && hasTxnId && hasDbname && hasIsolation && record.txnId != 0 &&
           !record.dbname.empty() && record.dbname.find('\n') == std::string::npos &&
           record.dbname.find('\r') == std::string::npos &&
           record.dbname.find('/') == std::string::npos &&
           record.dbname.find('\\') == std::string::npos &&
           record.dbname != "." && record.dbname != "..";
}

DBStatus StorageEngine::prepareTransaction(const std::string& xid) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    if (!transactionContext().ddlUndoActions.empty()) {
        // DDL undo callbacks are backend-local closures. Do not prepare a
        // transaction whose rollback semantics cannot survive this backend's
        // in-memory context; callers must commit/rollback it directly.
        return DBStatus::INVALID_VALUE;
    }

    // The preparing backend may own dirty heap, index, FSM or visibility-map
    // pages that a different backend will never see in its private caches.
    // PREPARE is therefore the hand-off boundary: publish all physical
    // effects before the prepared record can be completed elsewhere.
    if (!flushDatabaseCaches(transactionContext().txnDB)) {
        return DBStatus::IO_ERROR;
    }

    std::filesystem::path pdir = preparedDir();
    if (!std::filesystem::exists(pdir)) {
        std::filesystem::create_directories(pdir);
    }
    std::filesystem::path pfile = preparedPath(xid);
    if (std::filesystem::exists(pfile)) return DBStatus::DUPLICATE_KEY;

    std::ostringstream prepared;

    // Transaction metadata
    prepared << "PREPARED_FORMAT " << PreparedTransactionRecord::CURRENT_FORMAT << "\n";
    prepared << "TXN_ID " << transactionContext().currentTxnId << "\n";
    prepared << "DBNAME " << transactionContext().txnDB << "\n";
    prepared << "ISOLATION " << static_cast<int>(transactionContext().txnIsolationLevel) << "\n";
    prepared << "READONLY " << (transactionContext().readOnly ? 1 : 0) << "\n";

    // Held locks use a versioned, structured representation. A new process
    // must be able to reacquire the same advisory resources after restart;
    // thread IDs and internal namespace separators are not durable data.
    std::vector<LockManager::PreparedLockInfo> locks;
    if (!lockManager_.getPreparedLockInfos(locks)) return DBStatus::CORRUPTED_DATA;
    for (const auto& lock : locks) {
        const char* mode = preparedLockModeName(lock.mode);
        if (!mode || lock.dbname != transactionContext().txnDB || lock.table.empty()) {
            return DBStatus::CORRUPTED_DATA;
        }
        switch (lock.kind) {
            case LockManager::PreparedLockInfo::Kind::Table:
                prepared << "LOCK TABLE " << mode << " "
                         << preparedHexEncode(lock.table) << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Row:
                prepared << "LOCK ROW " << mode << " "
                         << preparedHexEncode(lock.table) << " " << lock.rid << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Page:
                prepared << "LOCK PAGE " << mode << " "
                         << preparedHexEncode(lock.table) << " " << lock.pageId << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Gap:
                prepared << "LOCK GAP " << preparedHexEncode(lock.table) << " "
                         << preparedHexEncode(lock.leftKey) << " "
                         << preparedHexEncode(lock.rightKey) << "\n";
                break;
        }
    }

    // Transaction log
    for (const auto& entry : transactionContext().txnLog) {
        prepared << "LOG ";
        if (entry.op == TxnLogEntry::Op::Insert) prepared << "INSERT";
        else if (entry.op == TxnLogEntry::Op::Update) prepared << "UPDATE";
        else if (entry.op == TxnLogEntry::Op::Delete) prepared << "DELETE";
        prepared << " " << entry.tableName << " " << entry.rowIdx << " ";
        for (unsigned char c : entry.rowData) {
            char buf[3];
            snprintf(buf, sizeof(buf), "%02x", c);
            prepared << buf;
        }
        prepared << "\n";
    }
    if (!writePreparedFileAtomically(pfile, prepared.str())) {
        return DBStatus::IO_ERROR;
    }
    const Lsn prepareLsn = walXactPrepare(transactionContext().txnDB,
                                           transactionContext().currentTxnId);
    WALManager* wal = getWAL(transactionContext().txnDB);
    if (prepareLsn == INVALID_LSN || !wal || !wal->XLogFlush(prepareLsn)) {
        (void)removePreparedFileDurably(pfile);
        return DBStatus::IO_ERROR;
    }

    if (!lockManager_.suspendCurrentLocksForPrepared(transactionContext().currentTxnId)) {
        (void)removePreparedFileDurably(pfile);
        return DBStatus::LOCK_CONFLICT;
    }

    // Remove from active set (prepared txns are not active for ReadView)
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(transactionContext().currentTxnId);
        activeTransactionDatabases_.erase(transactionContext().currentTxnId);
    }

    // Clear transaction state but KEEP locks (2PC semantics)
    transactionContext().txnLog.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().savepoints.clear();

    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_.erase(transactionContext().currentTxnId);
        ssiWriteSets_.erase(transactionContext().currentTxnId);
        ssiReadRelations_.erase(transactionContext().currentTxnId);
        ssiWriteRelations_.erase(transactionContext().currentTxnId);
        ssiReadPages_.erase(transactionContext().currentTxnId);
        ssiWritePages_.erase(transactionContext().currentTxnId);
        ssiReadIndexPredicates_.erase(transactionContext().currentTxnId);
        ssiWriteIndexKeys_.erase(transactionContext().currentTxnId);
        ssiOutEdges_.erase(transactionContext().currentTxnId);
        for (auto& [k, v] : ssiInEdges_) v.erase(transactionContext().currentTxnId);
        ssiInEdges_.erase(transactionContext().currentTxnId);
        for (auto& [k, v] : ssiOutEdges_) v.erase(transactionContext().currentTxnId);
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();

    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    // The database transaction mutex is a backend-local implementation lock;
    // it cannot be unlocked safely by COMMIT/ROLLBACK PREPARED on another
    // thread. Physical table/row/page/gap ownership has already been
    // transferred by LockManager, so release this session lock at PREPARE.
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    transactionContext().txnBackupPath.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    return DBStatus::OK;
}

DBStatus StorageEngine::commitPrepared(const std::string& xid) {
    if (transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    std::filesystem::path pfile = preparedPath(xid);
    if (!std::filesystem::exists(pfile)) return DBStatus::TABLE_NOT_FOUND;

    PreparedTransactionRecord record;
    if (!readPreparedRecord(pfile, record)) return DBStatus::CORRUPTED_DATA;
    const uint64_t savedTxnId = record.txnId;
    const std::string& savedDB = record.dbname;

    // WAL COMMIT PREPARED marker. Keep the prepared transaction durable and
    // retryable if WAL insertion or fsync fails.
    if (!flushDatabaseCaches(savedDB)) return DBStatus::IO_ERROR;
    WALManager* wal = getWAL(savedDB);
    if (!wal) return DBStatus::IO_ERROR;
    Lsn commitLsn = walXactCommit(savedDB, savedTxnId);
    if (commitLsn == INVALID_LSN || !wal->XLogFlush(commitLsn)) {
        return DBStatus::IO_ERROR;
    }

    CommitLog* clog = getCommitLog(savedDB);
    if (!clog) return DBStatus::IO_ERROR;
    clog->setStatus(savedTxnId, CommitLog::Status::Committed);
    if (!clog->flush()) return DBStatus::IO_ERROR;

    // Normal commit logic
    TxnIdGenerator::instance().notifyCommit(savedTxnId);
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(savedTxnId);
        activeTransactionDatabases_.erase(savedTxnId);
    }

    transactionContext().txnLog.clear();
    transactionContext().savepoints.clear();
    std::error_code backupEc;
    std::filesystem::remove_all(transactionBackupPath(savedDB, savedTxnId), backupEc);
    lockManager_.releasePreparedLocks(savedTxnId);
    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().txnBackupPath.clear();
    transactionContext().txnDB.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();

    return removePreparedFileDurably(pfile) ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::rollbackPrepared(const std::string& xid) {
    if (transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    std::filesystem::path pfile = preparedPath(xid);
    if (!std::filesystem::exists(pfile)) return DBStatus::TABLE_NOT_FOUND;

    PreparedTransactionRecord record;
    if (!readPreparedRecord(pfile, record)) return DBStatus::CORRUPTED_DATA;
    const uint64_t savedTxnId = record.txnId;
    const std::string& savedDB = record.dbname;

    // Temporarily restore state and use normal rollback
    transactionContext().currentTxnId = savedTxnId;
    transactionContext().txnDB = savedDB;
    transactionContext().txnBackupPath = transactionBackupPath(savedDB, savedTxnId).string();
    transactionContext().txnIsolationLevel = record.isolation;
    transactionContext().inTransaction = true;
    transactionContext().txnLog.clear();
    transactionContext().txnLog.reserve(record.log.size());
    for (const auto& entry : record.log) {
        TxnLogEntry restored;
        if (entry.op == PreparedTransactionRecord::LogEntry::Op::Insert) {
            restored.op = TxnLogEntry::Op::Insert;
        } else if (entry.op == PreparedTransactionRecord::LogEntry::Op::Update) {
            restored.op = TxnLogEntry::Op::Update;
        } else {
            restored.op = TxnLogEntry::Op::Delete;
        }
        restored.tableName = entry.tableName;
        restored.rowIdx = entry.rowIdx;
        restored.rowData = entry.rowData;
        transactionContext().txnLog.push_back(std::move(restored));
    }

    DBStatus res = rollbackTransaction();
    if (res != DBStatus::OK) return res;
    lockManager_.releasePreparedLocks(savedTxnId);
    return removePreparedFileDurably(pfile) ? DBStatus::OK : DBStatus::IO_ERROR;
}

std::vector<std::string> StorageEngine::listPreparedTransactions() const {
    std::vector<std::string> result;
    std::filesystem::path pdir = preparedDir();
    if (!std::filesystem::exists(pdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(pdir)) {
        if (entry.is_regular_file()) {
            result.push_back(entry.path().filename().string());
        }
    }
    return result;
}

// ========================================================================
// Savepoint support
// ========================================================================

DBStatus StorageEngine::savepoint(const std::string& name) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (transactionContext().transactionBackupDirty) {
        // A full DDL snapshot cannot safely describe a savepoint created
        // after the physical mutation. Fail closed until object-level DDL
        // savepoint images are available.
        return DBStatus::INVALID_VALUE;
    }
    transactionContext().savepoints[name] = {
        transactionContext().txnLog.size(),
        transactionContext().ddlUndoActions.size(),
        lockManager_.captureCheckpoint()
    };
    return DBStatus::OK;
}

DBStatus StorageEngine::rollbackToSavepoint(const std::string& name) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (transactionContext().transactionBackupDirty) return DBStatus::INVALID_VALUE;
    auto it = transactionContext().savepoints.find(name);
    if (it == transactionContext().savepoints.end()) return DBStatus::INVALID_VALUE;
    const size_t txnLogSpIdx = it->second.txnLogSize;
    const size_t ddlSpIdx = it->second.ddlUndoSize;
    if (txnLogSpIdx > transactionContext().txnLog.size() ||
        ddlSpIdx > transactionContext().ddlUndoActions.size()) {
        return DBStatus::INVALID_VALUE;
    }

    // Undo entries from end back to savepoint
    for (size_t i = transactionContext().txnLog.size(); i > txnLogSpIdx; --i) {
        auto& entry = transactionContext().txnLog[i - 1];
        PageAllocator* pa = getPageAllocator(transactionContext().txnDB, entry.tableName);
        TableSchema tbl = getTableSchema(transactionContext().txnDB, entry.tableName);
        if (entry.op == TxnLogEntry::Op::Insert) {
            // Remove from indexes first (row still exists)
            std::string insertedRow;
            if (readRowByRid(pa, entry.rowIdx, insertedRow, tbl)) {
                deleteRowToast(transactionContext().txnDB, entry.tableName, entry.rowIdx);
            }
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, entry.tableName);
            if (pkIdx) {
                if (!insertedRow.empty()) {
                    std::string pkVal = extractPKValue(insertedRow, tbl);
                    if (!pkVal.empty()) pkIdx->remove(pkVal);
                }
            }
            auto indexedCols = getIndexedColumns(transactionContext().txnDB, entry.tableName);
            for (const auto& colname : indexedCols) {
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) { colIdx = j; break; }
                }
                if (colIdx >= tbl.len) continue;
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, entry.tableName, colname);
                if (!secIdx) continue;
                if (!insertedRow.empty()) {
                    std::string val = extractColumnValue(insertedRow, tbl, colIdx);
                    if (!val.empty()) secIdx->removeMulti(val, entry.rowIdx);
                }
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                std::string key = buildCompositeKey(insertedRow, tbl, ci.columns);
                if (key.empty()) continue;
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, entry.tableName, ci.name);
                if (compositeIdx) compositeIdx->removeMulti(key, entry.rowIdx);
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) { colIdx = j; break; }
                }
                if (colIdx >= tbl.len) continue;
                std::string value = extractColumnValue(insertedRow, tbl, colIdx);
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (hashIdx && !value.empty()) hashIdx->remove(value, entry.rowIdx);
            }
            // Then remove the row from page
            uint32_t pageId; uint16_t slotId;
            decodeRid(entry.rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, entry.tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                page.remove(slotId);
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, entry.tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
        } else if (entry.op == TxnLogEntry::Op::Update) {
            uint32_t pageId; uint16_t slotId;
            decodeRid(entry.rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            std::string currentRow;
            bool foundCurrent = false;
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, entry.tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                // Read current row data before restoring (needed to remove stale index entries)
                const char* currentData = nullptr;
                size_t currentLen = 0;
                if (page.read(slotId, currentData, currentLen) && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    currentRow = stripRowHeader(currentData, currentLen, tbl.formatVersion, tbl.len);
                    foundCurrent = true;
                } else {
                    std::string targetPk = extractPKValue(entry.rowData, tbl);
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (foundCurrent || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(rowData, tbl);
                        if (pk == targetPk) {
                            currentRow = rowData;
                            foundCurrent = true;
                        }
                    });
                }
                if (foundCurrent) {
                    deleteToastForRowExcept(transactionContext().txnDB, entry.tableName,
                                            currentRow, entry.rowData);
                }
                // Restore old row data
                if (page.read(slotId, currentData, currentLen) && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), entry.rowData, tbl.formatVersion, tbl.len);
                    setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                } else {
                    std::string targetPk = extractPKValue(entry.rowData, tbl);
                    bool restored = false;
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (restored || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(rowData, tbl);
                        if (pk == targetPk) {
                            std::string fullRow = replaceRowData(
                                std::string(data, len), entry.rowData, tbl.formatVersion, tbl.len);
                            setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            page.update(sid, fullRow.data(), fullRow.size());
                            restored = true;
                        }
                    });
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, entry.tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Rebuild indexes: remove current (stale) values then insert restored values
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, entry.tableName);
            if (pkIdx) {
                if (foundCurrent) {
                    std::string currentPk = extractPKValue(currentRow, tbl);
                    if (!currentPk.empty()) pkIdx->remove(currentPk);
                }
                std::string newPk = extractPKValue(entry.rowData, tbl);
                if (!newPk.empty()) pkIdx->insert(newPk, entry.rowIdx);
            }
            auto indexedCols = getIndexedColumns(transactionContext().txnDB, entry.tableName);
            for (const auto& colname : indexedCols) {
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) { colIdx = j; break; }
                }
                if (colIdx >= tbl.len) continue;
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, entry.tableName, colname);
                if (!secIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = extractColumnValue(currentRow, tbl, colIdx);
                    if (!currentVal.empty()) secIdx->removeMulti(currentVal, entry.rowIdx);
                }
                std::string val = extractColumnValue(entry.rowData, tbl, colIdx);
                if (!val.empty()) secIdx->insertMulti(val, entry.rowIdx);
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, entry.tableName)) {
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, entry.tableName, ci.name);
                if (!compositeIdx) continue;
                if (foundCurrent) {
                    std::string currentKey = buildCompositeKey(currentRow, tbl, ci.columns);
                    if (!currentKey.empty()) compositeIdx->removeMulti(currentKey, entry.rowIdx);
                }
                std::string oldKey = buildCompositeKey(entry.rowData, tbl, ci.columns);
                if (!oldKey.empty()) compositeIdx->insertMulti(oldKey, entry.rowIdx);
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, entry.tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!hashIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = extractColumnValue(currentRow, tbl, colIdx);
                    if (!currentVal.empty()) hashIdx->remove(currentVal, entry.rowIdx);
                }
                std::string oldVal = extractColumnValue(entry.rowData, tbl, colIdx);
                if (!oldVal.empty()) hashIdx->insert(oldVal, entry.rowIdx);
            }
        } else if (entry.op == TxnLogEntry::Op::Delete) {
            uint32_t pageId; uint16_t slotId;
            decodeRid(entry.rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                const char* currentData = nullptr;
                size_t currentLen = 0;
                walPageImage(transactionContext().txnDB, entry.tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                if (page.read(slotId, currentData, currentLen) &&
                    currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), entry.rowData,
                        tbl.formatVersion, tbl.len);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, entry.tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, entry.tableName);
            if (pkIdx) {
                std::string pkVal = extractPKValue(entry.rowData, tbl);
                if (!pkVal.empty()) pkIdx->insert(pkVal, entry.rowIdx);
            }
            auto indexedCols = getIndexedColumns(transactionContext().txnDB, entry.tableName);
            for (const auto& colname : indexedCols) {
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) { colIdx = j; break; }
                }
                if (colIdx >= tbl.len) continue;
                BPTree* secIdx = getSecondaryIndex(transactionContext().txnDB, entry.tableName, colname);
                if (!secIdx) continue;
                std::string val = extractColumnValue(entry.rowData, tbl, colIdx);
                if (!val.empty()) secIdx->insertMulti(val, entry.rowIdx);
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, entry.tableName)) {
                BPTree* compositeIdx = getCompositeIndexTree(
                    transactionContext().txnDB, entry.tableName, ci.name);
                if (!compositeIdx) continue;
                std::string key = buildCompositeKey(entry.rowData, tbl, ci.columns);
                if (!key.empty()) compositeIdx->insertMulti(key, entry.rowIdx);
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, entry.tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!hashIdx) continue;
                std::string value = extractColumnValue(entry.rowData, tbl, colIdx);
                if (!value.empty()) hashIdx->insert(value, entry.rowIdx);
            }
        }
    }
    transactionContext().txnLog.resize(txnLogSpIdx);

    // DDL CREATE undo actions follow the same savepoint boundary. Row undo
    // above runs first so a newly-created relation remains available while
    // its rows are being removed.
    bool ddlUndoOk = true;
    for (size_t i = transactionContext().ddlUndoActions.size(); i > ddlSpIdx; --i) {
        try {
            if (!transactionContext().ddlUndoActions[i - 1]()) ddlUndoOk = false;
        } catch (...) {
            ddlUndoOk = false;
        }
    }
    transactionContext().ddlUndoActions.resize(ddlSpIdx);
    lockManager_.rollbackToCheckpoint(it->second.lockCheckpoint);

    // Remove all savepoints created after this one
    for (auto sit = transactionContext().savepoints.begin(); sit != transactionContext().savepoints.end(); ) {
        if (sit->second.txnLogSize > txnLogSpIdx || sit->second.ddlUndoSize > ddlSpIdx) {
            sit = transactionContext().savepoints.erase(sit);
        }
        else ++sit;
    }
    return ddlUndoOk ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::releaseSavepoint(const std::string& name) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    auto it = transactionContext().savepoints.find(name);
    if (it == transactionContext().savepoints.end()) return DBStatus::INVALID_VALUE;
    transactionContext().savepoints.erase(it);
    return DBStatus::OK;
}

// ========================================================================
// Row-Level Security (RLS)
// ========================================================================

static bool writePolicyFile(const std::filesystem::path& path,
                            const std::vector<StorageEngine::RowPolicy>& policies) {
    std::ofstream ofs(path);
    if (!ofs) return false;
    for (const auto& p : policies) {
        ofs << "POLICY " << escapeString(p.name) << " " << p.cmd;
        ofs << " AS:" << (p.permissive ? "PERMISSIVE" : "RESTRICTIVE");
        ofs << " USING:" << escapeString(p.usingExpr);
        ofs << " WITHCHECK:" << escapeString(p.withCheckExpr);
        ofs << " ROLES:";
        for (size_t i = 0; i < p.roles.size(); ++i) {
            if (i > 0) ofs << ",";
            ofs << escapeString(p.roles[i]);
        }
        ofs << "\n";
    }
    return true;
}

std::filesystem::path StorageEngine::rlsPath(const std::string& dbname, const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".rls");
}

DBStatus StorageEngine::createPolicy(const std::string& dbname, const std::string& tablename,
                                      const RowPolicy& policy) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    for (const auto& p : policies) {
        if (p.name == policy.name) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    policies.push_back(policy);
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

DBStatus StorageEngine::alterPolicy(const std::string& dbname, const std::string& tablename,
                                     const std::string& policyName, const RowPolicy& policy) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    bool found = false;
    for (const auto& p : policies) {
        if (p.name == policy.name && policy.name != policyName) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    for (auto& p : policies) {
        if (p.name == policyName) {
            p = policy;
            found = true;
            break;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

DBStatus StorageEngine::dropPolicy(const std::string& dbname, const std::string& tablename,
                                    const std::string& policyName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    bool found = false;
    for (auto it = policies.begin(); it != policies.end(); ) {
        if (it->name == policyName) {
            it = policies.erase(it);
            found = true;
        } else {
            ++it;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

std::vector<StorageEngine::RowPolicy> StorageEngine::getPolicies(const std::string& dbname,
                                                                   const std::string& tablename) const {
    std::vector<RowPolicy> result;
    auto rpath = rlsPath(dbname, tablename);
    if (!std::filesystem::exists(rpath)) return result;
    std::ifstream ifs(rpath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.substr(0, 7) != "POLICY ") continue;
        size_t pos = 7;
        size_t sp = line.find(' ', pos);
        if (sp == std::string::npos) continue;
        RowPolicy p;
        p.name = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 1;
        sp = line.find(" AS:", pos);
        if (sp == std::string::npos) continue;
        p.cmd = line.substr(pos, sp - pos);
        pos = sp + 4;
        size_t modeEnd = line.find(" USING:", pos);
        if (modeEnd == std::string::npos) continue;
        const std::string mode = line.substr(pos, modeEnd - pos);
        if (mode == "PERMISSIVE") p.permissive = true;
        else if (mode == "RESTRICTIVE") p.permissive = false;
        else continue;
        pos = modeEnd + 7;
        sp = line.find(" WITHCHECK:", pos);
        if (sp == std::string::npos) continue;
        p.usingExpr = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 11;
        sp = line.find(" ROLES:", pos);
        if (sp == std::string::npos) continue;
        p.withCheckExpr = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 7;
        std::string rolesStr = line.substr(pos);
        if (!rolesStr.empty()) {
            std::stringstream ss(rolesStr);
            std::string role;
            while (std::getline(ss, role, ',')) {
                if (!role.empty()) p.roles.push_back(unescapeString(role));
            }
        }
        result.push_back(p);
    }
    return result;
}

std::vector<StorageEngine::RowPolicy> StorageEngine::getApplicablePolicies(
    const std::string& dbname, const std::string& tablename,
    const std::string& cmd, const std::string& username) const {
    auto all = getPolicies(dbname, tablename);
    std::vector<RowPolicy> result;
    for (const auto& p : all) {
        if (p.cmd != "ALL" && p.cmd != cmd) continue;
        if (p.roles.empty()) {
            result.push_back(p);
        } else {
            for (const auto& r : p.roles) {
                if (toLowerUtf8(r) == "public" || r == username ||
                    userHasRole(username, r)) {
                    result.push_back(p);
                    break;
                }
            }
        }
    }
    return result;
}

DBStatus StorageEngine::enableRowLevelSecurity(const std::string& dbname, const std::string& tablename,
                                                  bool force) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    tbl.rowLevelSecurity = true;
    tbl.forceRowLevelSecurity = force;
    std::ofstream out(schemaPath(dbname, tablename), std::ios::binary);
    writeSchema(out, tbl);
    invalidateCatalogSchema(dbname, tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::disableRowLevelSecurity(const std::string& dbname, const std::string& tablename) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    tbl.rowLevelSecurity = false;
    tbl.forceRowLevelSecurity = false;
    std::ofstream out(schemaPath(dbname, tablename), std::ios::binary);
    writeSchema(out, tbl);
    invalidateCatalogSchema(dbname, tablename);
    return DBStatus::OK;
}

// ========================================================================
// Table-level permissions
// ========================================================================

std::filesystem::path StorageEngine::permPath(const std::string& dbname) const {
    return dbPath(dbname) / ".permissions";
}

static std::filesystem::path grantChainPath(const std::filesystem::path& dbPath) {
    return dbPath / ".grant_chain";
}

std::filesystem::path StorageEngine::seqPath(const std::string& dbname, const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".seq");
}

std::filesystem::path StorageEngine::seclabelPath(const std::string& dbname) const {
    return dbPath(dbname) / ".security_labels";
}

void StorageEngine::setSecurityLabel(const std::string& dbname, const std::string& objType,
                                     const std::string& objName, const std::string& label) {
    auto spath = seclabelPath(dbname);
    std::map<std::string, std::string> labels; // key=objType|objName -> label
    if (std::filesystem::exists(spath)) {
        std::ifstream ifs(spath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            size_t p1 = line.find(' ');
            size_t p2 = line.find(' ', p1 + 1);
            if (p1 == std::string::npos || p2 == std::string::npos) continue;
            std::string key = line.substr(0, p1) + "|" + line.substr(p1 + 1, p2 - p1 - 1);
            labels[key] = line.substr(p2 + 1);
        }
    }
    std::string key = objType + "|" + objName;
    if (label.empty()) {
        labels.erase(key);
    } else {
        labels[key] = label;
    }
    std::ofstream ofs(spath);
    for (const auto& kv : labels) {
        size_t dp = kv.first.find('|');
        std::string ot = kv.first.substr(0, dp);
        std::string on = kv.first.substr(dp + 1);
        ofs << ot << " " << on << " " << kv.second << "\n";
    }
}

std::string StorageEngine::getSecurityLabel(const std::string& dbname, const std::string& objType,
                                            const std::string& objName) const {
    auto spath = seclabelPath(dbname);
    if (!std::filesystem::exists(spath)) return "";
    std::ifstream ifs(spath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string ot, on, lab;
        ss >> ot >> on;
        std::getline(ss, lab);
        if (!lab.empty() && lab[0] == ' ') lab = lab.substr(1);
        if (ot == objType && on == objName) return lab;
    }
    return "";
}

std::vector<std::tuple<std::string, std::string, std::string>> StorageEngine::getAllSecurityLabels(
    const std::string& dbname) const {
    std::vector<std::tuple<std::string, std::string, std::string>> result;
    auto spath = seclabelPath(dbname);
    if (!std::filesystem::exists(spath)) return result;
    std::ifstream ifs(spath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string ot, on, lab;
        ss >> ot >> on;
        std::getline(ss, lab);
        if (!lab.empty() && lab[0] == ' ') lab = lab.substr(1);
        result.emplace_back(ot, on, lab);
    }
    return result;
}

// ========================================================================
// Default Privileges
// ========================================================================
static std::filesystem::path defaultPrivPath(const std::filesystem::path& dbPath) {
    return dbPath / ".default_privs";
}

void StorageEngine::addDefaultPrivilege(const std::string& dbname, const std::string& owner,
                                        const std::string& schema, const std::string& objType,
                                        const std::string& privilege, const std::string& grantee) {
    auto dpp = defaultPrivPath(dbPath(dbname));
    {
        std::ifstream ifs(dpp);
        std::string line;
        while (std::getline(ifs, line)) {
            std::stringstream ss(line);
            std::string o, s, t, p, g;
            ss >> o >> s >> t >> p >> g;
            if (o == owner && s == schema && t == objType && p == privilege && g == grantee) {
                return;
            }
        }
    }
    std::ofstream ofs(dpp, std::ios::app);
    ofs << owner << " " << schema << " " << objType << " " << privilege << " " << grantee << "\n";
}

void StorageEngine::removeDefaultPrivilege(const std::string& dbname, const std::string& owner,
                                           const std::string& schema, const std::string& objType,
                                           const std::string& privilege, const std::string& grantee) {
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return;
    std::vector<std::string> remaining;
    {
        std::ifstream ifs(dpp);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string o, s, t, p, g;
            ss >> o >> s >> t >> p >> g;
            if (o == owner && s == schema && t == objType && p == privilege && g == grantee) continue;
            remaining.push_back(line);
        }
    }
    std::ofstream ofs(dpp);
    for (const auto& r : remaining) ofs << r << "\n";
}

void StorageEngine::applyDefaultPrivileges(const std::string& dbname, const std::string& schema,
                                           const std::string& objType, const std::string& objName,
                                           const std::string& owner) const {
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return;
    std::ifstream ifs(dpp);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string o, s, t, p, g;
        ss >> o >> s >> t >> p >> g;
        if (o != owner || s != schema || t != objType) continue;
        TablePrivilege priv;
        if (p == "select") priv = TablePrivilege::Select;
        else if (p == "insert") priv = TablePrivilege::Insert;
        else if (p == "update") priv = TablePrivilege::Update;
        else if (p == "delete") priv = TablePrivilege::Delete;
        else if (p == "all") priv = TablePrivilege::All;
        else if (p == "usage") priv = TablePrivilege::Usage;
        else if (p == "execute") priv = TablePrivilege::Execute;
        else continue;
        const_cast<StorageEngine*>(this)->grant(dbname, objName, g, priv, {}, false, owner);
    }
}

std::vector<std::tuple<std::string, std::string, std::string, std::string, std::string>>
StorageEngine::getDefaultPrivileges(const std::string& dbname) const {
    std::vector<std::tuple<std::string, std::string, std::string, std::string, std::string>> result;
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return result;
    std::ifstream ifs(dpp);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string o, s, t, p, g;
        ss >> o >> s >> t >> p >> g;
        result.emplace_back(o, s, t, p, g);
    }
    return result;
}

int64_t StorageEngine::readNextSeq(const std::string& dbname, const std::string& tablename, const std::string& colname) {
    const std::string key = dbname + "/" + tablename;
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    auto& state = seqFileCache_[key];
    if (!state.loaded) {
        auto path = seqPath(dbname, tablename);
        if (std::filesystem::exists(path)) {
            std::ifstream ifs(path);
            if (ifs) {
                std::string line;
                while (std::getline(ifs, line)) {
                    size_t sp = line.find(' ');
                    if (sp == std::string::npos) continue;
                    try {
                        state.values[line.substr(0, sp)] = std::stoll(line.substr(sp + 1));
                    } catch (...) {}
                }
            }
        }
        state.loaded = true;
    }
    auto it = state.values.find(colname);
    return it == state.values.end() ? 1 : it->second;
}

void StorageEngine::writeNextSeq(const std::string& dbname, const std::string& tablename, const std::string& colname, int64_t val) {
    const std::string key = dbname + "/" + tablename;
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    auto& state = seqFileCache_[key];
    if (!state.loaded) {
        // Preserve other columns' counters on first touch of this table.
        auto path = seqPath(dbname, tablename);
        if (std::filesystem::exists(path)) {
            std::ifstream ifs(path);
            if (ifs) {
                std::string line;
                while (std::getline(ifs, line)) {
                    size_t sp = line.find(' ');
                    if (sp == std::string::npos) continue;
                    try {
                        state.values[line.substr(0, sp)] = std::stoll(line.substr(sp + 1));
                    } catch (...) {}
                }
            }
        }
        state.loaded = true;
    }
    state.values[colname] = val;
    state.dirty = true;
}

// Persist every dirty sequence file. Called at transaction boundaries so a
// multi-row INSERT rewrites <table>.seq once instead of twice per row.
void StorageEngine::flushDeferredSequences() {
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    for (auto& [key, state] : seqFileCache_) {
        if (!state.dirty) continue;
        const size_t slash = key.find('/');
        if (slash == std::string::npos) { state.dirty = false; continue; }
        const std::string dbname = key.substr(0, slash);
        const std::string tablename = key.substr(slash + 1);
        auto path = seqPath(dbname, tablename);
        std::error_code ec;
        std::filesystem::create_directories(path.parent_path(), ec);
        std::ofstream ofs(path);
        for (const auto& p : state.values) {
            ofs << p.first << ' ' << p.second << '\n';
        }
        state.dirty = false;
    }
}

void StorageEngine::removeSeq(const std::string& dbname, const std::string& tablename) {
    {
        std::lock_guard<std::mutex> lock(seqCacheMutex_);
        seqFileCache_.erase(dbname + "/" + tablename);
    }
    auto path = seqPath(dbname, tablename);
    if (std::filesystem::exists(path)) {
        std::filesystem::remove(path);
    }
}

void StorageEngine::resetSequence(const std::string& dbname, const std::string& tablename,
                                  const std::string& colname, int64_t val) {
    writeNextSeq(dbname, tablename, colname, val);
}

// ========================================================================
// Domain support
// ========================================================================
static std::filesystem::path domainPath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".domains";
}

DBStatus StorageEngine::createDomain(const std::string& dbname, const DomainInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (info.name.empty() || !validStoredIdentifier(info.name, MAX_TABLE_NAME_LEN) ||
        info.name.find('|') != std::string::npos) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = domainPath(dbname);
    auto existing = getDomain(dbname, info.name);
    if (!existing.name.empty()) return DBStatus::TABLE_ALREADY_EXISTS;

    std::vector<std::string> lines;
    if (std::filesystem::exists(path)) {
        std::ifstream input(path);
        if (!input) return DBStatus::IO_ERROR;
        std::string line;
        while (std::getline(input, line)) lines.push_back(std::move(line));
        if (input.bad()) return DBStatus::IO_ERROR;
    }
    std::ostringstream serialized;
    for (const auto& line : lines) serialized << line << '\n';
    serialized << info.name << "|" << info.baseType << "|" << info.defaultValue << "|"
               << info.checkExpr << "|" << info.constraintName << '\n';
    return index_file::writeAtomically(path, serialized.str())
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::alterDomain(const std::string& dbname, const std::string& name,
                                    const DomainInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    if (info.name != name && !getDomain(dbname, info.name).name.empty()) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ifstream ifs(path);
    std::vector<DomainInfo> domains;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp1 = line.find('|');
        if (sp1 == std::string::npos) continue;
        size_t sp2 = line.find('|', sp1 + 1);
        size_t sp3 = (sp2 == std::string::npos) ? std::string::npos : line.find('|', sp2 + 1);
        size_t sp4 = (sp3 == std::string::npos) ? std::string::npos : line.find('|', sp3 + 1);
        DomainInfo current;
        current.name = line.substr(0, sp1);
        current.baseType = (sp2 == std::string::npos) ? "" : line.substr(sp1 + 1, sp2 - sp1 - 1);
        current.defaultValue = (sp2 == std::string::npos)
            ? ""
            : ((sp3 == std::string::npos) ? line.substr(sp2 + 1) : line.substr(sp2 + 1, sp3 - sp2 - 1));
        current.checkExpr = (sp3 == std::string::npos)
            ? ""
            : ((sp4 == std::string::npos) ? line.substr(sp3 + 1) : line.substr(sp3 + 1, sp4 - sp3 - 1));
        if (sp4 != std::string::npos) current.constraintName = line.substr(sp4 + 1);
        if (current.name == name) {
            domains.push_back(info);
            found = true;
        } else {
            domains.push_back(current);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    if (!ofs) return DBStatus::INVALID_VALUE;
    for (const auto& d : domains) {
        ofs << d.name << "|" << d.baseType << "|" << d.defaultValue << "|"
            << d.checkExpr << "|" << d.constraintName << "\n";
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::dropDomain(const std::string& dbname, const std::string& name) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::ifstream ifs(path);
    std::vector<std::string> lines;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos && line.substr(0, sp) == name) {
            found = true;
        } else {
            lines.push_back(line);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    for (const auto& l : lines) ofs << l << '\n';
    return DBStatus::OK;
}

StorageEngine::DomainInfo StorageEngine::getDomain(const std::string& dbname, const std::string& name) const {
    DomainInfo result;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp1 = line.find('|');
        if (sp1 == std::string::npos) continue;
        if (line.substr(0, sp1) != name) continue;
        size_t sp2 = line.find('|', sp1 + 1);
        size_t sp3 = (sp2 == std::string::npos) ? std::string::npos : line.find('|', sp2 + 1);
        size_t sp4 = (sp3 == std::string::npos) ? std::string::npos : line.find('|', sp3 + 1);
        result.name = name;
        result.baseType = (sp2 == std::string::npos) ? "" : line.substr(sp1 + 1, sp2 - sp1 - 1);
        result.defaultValue = (sp2 == std::string::npos)
            ? ""
            : ((sp3 == std::string::npos) ? line.substr(sp2 + 1) : line.substr(sp2 + 1, sp3 - sp2 - 1));
        result.checkExpr = (sp3 == std::string::npos)
            ? ""
            : ((sp4 == std::string::npos) ? line.substr(sp3 + 1) : line.substr(sp3 + 1, sp4 - sp3 - 1));
        if (sp4 != std::string::npos) result.constraintName = line.substr(sp4 + 1);
        break;
    }
    return result;
}

std::vector<std::string> StorageEngine::getDomainNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos) result.push_back(line.substr(0, sp));
    }
    return result;
}

// ========================================================================
// Composite types (ROW types)
// ========================================================================
static std::filesystem::path compositeTypePath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".types";
}

DBStatus StorageEngine::createCompositeType(const std::string& dbname, const CompositeType& ct) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = compositeTypePath(dbname);
    if (isCompositeType(dbname, ct.name)) return DBStatus::TABLE_ALREADY_EXISTS;
    std::ofstream ofs(path, std::ios::app);
    if (!ofs) return DBStatus::INVALID_VALUE;
    ofs << ct.name;
    for (const auto& f : ct.fields) {
        ofs << "|" << f.first << ":" << f.second;
    }
    ofs << '\n';
    return DBStatus::OK;
}

DBStatus StorageEngine::alterCompositeType(const std::string& dbname, const std::string& name,
                                           const CompositeType& ct) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = compositeTypePath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    if (ct.name != name && isCompositeType(dbname, ct.name)) return DBStatus::TABLE_ALREADY_EXISTS;
    std::ifstream ifs(path);
    std::vector<CompositeType> types;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp == std::string::npos) continue;
        CompositeType current;
        current.name = line.substr(0, sp);
        size_t pos = sp + 1;
        while (pos < line.size()) {
            size_t next = line.find('|', pos);
            std::string fieldDef = (next == std::string::npos) ? line.substr(pos) : line.substr(pos, next - pos);
            size_t colon = fieldDef.find(':');
            if (colon != std::string::npos) {
                current.fields.emplace_back(fieldDef.substr(0, colon), fieldDef.substr(colon + 1));
            }
            pos = (next == std::string::npos) ? line.size() : next + 1;
        }
        if (current.name == name) {
            types.push_back(ct);
            found = true;
        } else {
            types.push_back(current);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    if (!ofs) return DBStatus::INVALID_VALUE;
    for (const auto& t : types) {
        ofs << t.name;
        for (const auto& f : t.fields) ofs << "|" << f.first << ":" << f.second;
        ofs << '\n';
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::dropCompositeType(const std::string& dbname, const std::string& name) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = compositeTypePath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::ifstream ifs(path);
    std::vector<std::string> lines;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos && line.substr(0, sp) == name) {
            found = true;
        } else {
            lines.push_back(line);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    for (const auto& l : lines) ofs << l << '\n';
    return DBStatus::OK;
}

StorageEngine::CompositeType StorageEngine::getCompositeType(const std::string& dbname, const std::string& name) const {
    CompositeType result;
    auto path = compositeTypePath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp == std::string::npos || line.substr(0, sp) != name) continue;
        result.name = name;
        size_t pos = sp + 1;
        while (pos < line.size()) {
            size_t next = line.find('|', pos);
            std::string fieldDef = (next == std::string::npos) ? line.substr(pos) : line.substr(pos, next - pos);
            size_t colon = fieldDef.find(':');
            if (colon != std::string::npos) {
                result.fields.emplace_back(fieldDef.substr(0, colon), fieldDef.substr(colon + 1));
            }
            pos = (next == std::string::npos) ? line.size() : next + 1;
        }
        break;
    }
    return result;
}

std::vector<std::string> StorageEngine::getCompositeTypeNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto path = compositeTypePath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos) result.push_back(line.substr(0, sp));
    }
    return result;
}

bool StorageEngine::isCompositeType(const std::string& dbname, const std::string& name) const {
    return !getCompositeType(dbname, name).name.empty();
}

// ========================================================================
// Enum type support
// ========================================================================
static std::filesystem::path enumPath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".enums";
}

DBStatus StorageEngine::createEnumType(const std::string& dbname, const EnumType& et) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto existing = getEnumType(dbname, et.name);
    if (!existing.name.empty()) return DBStatus::TABLE_ALREADY_EXISTS;
    std::ofstream ofs(enumPath(dbname), std::ios::app);
    if (!ofs) return DBStatus::INVALID_VALUE;
    ofs << et.name;
    for (const auto& label : et.labels) {
        ofs << "|" << label;
    }
    ofs << "\n";
    return DBStatus::OK;
}

DBStatus StorageEngine::dropEnumType(const std::string& dbname, const std::string& name) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = enumPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::ifstream ifs(path);
    std::vector<std::string> lines;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos && line.substr(0, sp) == name) {
            found = true;
        } else {
            lines.push_back(line);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    for (const auto& l : lines) ofs << l << '\n';
    return DBStatus::OK;
}

DBStatus StorageEngine::updateEnumType(const std::string& dbname, const EnumType& et) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = enumPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::ifstream ifs(path);
    std::vector<std::string> lines;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        std::string lname = (sp == std::string::npos) ? line : line.substr(0, sp);
        if (lname == et.name) {
            found = true;
            std::string rebuilt = et.name;
            for (const auto& label : et.labels) rebuilt += "|" + label;
            lines.push_back(rebuilt);
        } else {
            lines.push_back(line);
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ofstream ofs(path, std::ios::trunc);
    for (const auto& l : lines) ofs << l << '\n';
    return DBStatus::OK;
}

StorageEngine::EnumType StorageEngine::getEnumType(const std::string& dbname,
                                                    const std::string& name) const {
    EnumType result;
    auto path = enumPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp == std::string::npos || line.substr(0, sp) != name) continue;
        result.name = name;
        size_t pos = sp + 1;
        while (pos < line.size()) {
            size_t next = line.find('|', pos);
            if (next == std::string::npos) {
                result.labels.push_back(line.substr(pos));
                break;
            } else {
                result.labels.push_back(line.substr(pos, next - pos));
                pos = next + 1;
            }
        }
        break;
    }
    return result;
}

std::vector<std::string> StorageEngine::getEnumTypeNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto path = enumPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sp = line.find('|');
        if (sp != std::string::npos) result.push_back(line.substr(0, sp));
    }
    return result;
}

std::vector<std::string> StorageEngine::getInheritedChildren(const std::string& dbname,
                                                             const std::string& parentName) const {
    std::vector<std::string> children;
    auto inhPath = std::filesystem::path(dbPath(dbname)) / ".inherits";
    if (!std::filesystem::exists(inhPath)) return children;
    std::ifstream ifs(inhPath);
    if (!ifs) return children;
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sep = line.find('|');
        if (sep == std::string::npos) continue;
        std::string parent = line.substr(0, sep);
        std::string child = line.substr(sep + 1);
        if (parent == parentName) children.push_back(child);
    }
    return children;
}

// ========================================================================
// Advisory locks (session-level)
// ========================================================================
bool StorageEngine::advisoryLock(int64_t key) {
    std::lock_guard<std::mutex> lock(advisoryMutex_);
    auto it = advisoryLocks_.find(key);
    if (it == advisoryLocks_.end()) {
        advisoryLocks_[key] = 1;
        return true;
    }
    if (it->second > 0) {
        ++it->second;
        return true;
    }
    return false; // held by shared lock
}

bool StorageEngine::advisoryUnlock(int64_t key) {
    std::lock_guard<std::mutex> lock(advisoryMutex_);
    auto it = advisoryLocks_.find(key);
    if (it == advisoryLocks_.end() || it->second <= 0) return false;
    if (--it->second == 0) advisoryLocks_.erase(it);
    return true;
}

bool StorageEngine::advisoryLockShared(int64_t key) {
    std::lock_guard<std::mutex> lock(advisoryMutex_);
    auto it = advisoryLocks_.find(key);
    if (it == advisoryLocks_.end()) {
        advisoryLocks_[key] = -1;
        return true;
    }
    if (it->second < 0) {
        --it->second;
        return true;
    }
    return false; // held by exclusive lock
}

bool StorageEngine::advisoryUnlockShared(int64_t key) {
    std::lock_guard<std::mutex> lock(advisoryMutex_);
    auto it = advisoryLocks_.find(key);
    if (it == advisoryLocks_.end() || it->second >= 0) return false;
    if (++it->second == 0) advisoryLocks_.erase(it);
    return true;
}

bool StorageEngine::advisoryLockExists(int64_t key) const {
    std::lock_guard<std::mutex> lock(advisoryMutex_);
    return advisoryLocks_.find(key) != advisoryLocks_.end();
}

// Auto-VACUUM: trigger vacuum when dead tuple count exceeds threshold
void StorageEngine::maybeAutoVacuum(const std::string& dbname,
                                    const std::string& tablename) {
    if (!g_config.autoVacuumEnabled) return;
    auto key = std::make_pair(dbname, tablename);
    size_t count = 0;
    {
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        auto it = deadTupleCounts_.find(key);
        if (it == deadTupleCounts_.end()) return;
        count = it->second;
    }
    if (count >= static_cast<size_t>(g_config.autoVacuumThreshold)) {
        vacuum(dbname, tablename);
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        deadTupleCounts_[key] = 0;
    }
}

size_t StorageEngine::getDeadTupleCount(const std::string& dbname,
                                        const std::string& tablename) const {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(deadTupleMutex_);
    auto it = deadTupleCounts_.find(key);
    return (it != deadTupleCounts_.end()) ? it->second : 0;
}

void StorageEngine::resetDeadTupleCount(const std::string& dbname,
                                        const std::string& tablename) {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(deadTupleMutex_);
    deadTupleCounts_[key] = 0;
}

void StorageEngine::recordModification(const std::string& dbname,
                                       const std::string& tablename,
                                       size_t delta) {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(modifyMutex_);
    modifyCounts_[key] += delta;
}

void StorageEngine::maybeAutoAnalyze(const std::string& dbname,
                                     const std::string& tablename) {
    if (!g_config.autoAnalyzeEnabled) return;
    auto key = std::make_pair(dbname, tablename);
    size_t count = 0;
    {
        std::lock_guard<std::mutex> lock(modifyMutex_);
        auto it = modifyCounts_.find(key);
        if (it == modifyCounts_.end()) return;
        count = it->second;
    }
    if (count >= static_cast<size_t>(g_config.autoAnalyzeThreshold)) {
        analyzeTable(dbname, tablename);
        std::lock_guard<std::mutex> lock(modifyMutex_);
        modifyCounts_[key] = 0;
    }
}

static std::string privToStr(StorageEngine::TablePrivilege p) {
    switch (p) {
        case StorageEngine::TablePrivilege::Select: return "select";
        case StorageEngine::TablePrivilege::Insert: return "insert";
        case StorageEngine::TablePrivilege::Update: return "update";
        case StorageEngine::TablePrivilege::Delete: return "delete";
        case StorageEngine::TablePrivilege::All: return "all";
        case StorageEngine::TablePrivilege::Usage: return "usage";
        case StorageEngine::TablePrivilege::Execute: return "execute";
    }
    return "";
}

// Permission entry: user|table|priv -> set of columns (empty = table-level)
static std::string permKey(const std::string& u, const std::string& t, const std::string& p) {
    return u + "|" + t + "|" + p;
}

static std::vector<std::string> parseColumns(const std::string& colsStr) {
    std::vector<std::string> cols;
    std::stringstream ss(colsStr);
    std::string col;
    while (std::getline(ss, col, ',')) {
        if (!col.empty()) cols.push_back(col);
    }
    return cols;
}

static std::string joinColumns(const std::vector<std::string>& cols) {
    std::string s;
    for (size_t i = 0; i < cols.size(); ++i) {
        if (i > 0) s += ",";
        s += cols[i];
    }
    return s;
}

static constexpr const char* GRANT_OPTION_MARK = "__grant__";

// PostgreSQL ACL entries can target the session role, any role inherited by
// that session role, or PUBLIC. Keep this resolution in the storage ACL
// implementation so table- and column-level checks use identical semantics.
static bool aclGranteeMatches(const std::string& grantee, const std::string& username) {
    return grantee == username || grantee == "public" || userHasRole(username, grantee);
}

// PostgreSQL table owners have implicit privileges and grant options. Keep
// this in the same ACL resolution layer as explicit grants so AST and legacy
// DML paths cannot disagree about owner access.
static bool tableOwnerMatches(const StorageEngine& engine,
                              const std::string& dbname,
                              const std::string& tablename,
                              const std::string& username) {
    if (username.empty() || !engine.tableExists(dbname, tablename)) return false;
    return engine.getTableSchema(dbname, tablename).owner == username;
}

static bool colsEmptyIgnoreGrant(const std::string& colsStr) {
    if (colsStr.empty()) return true;
    // colsStr may start with space
    size_t start = 0;
    while (start < colsStr.size() && std::isspace(static_cast<unsigned char>(colsStr[start]))) ++start;
    if (start >= colsStr.size()) return true;
    // Check if remaining is only __grant__
    std::string rest = colsStr.substr(start);
    auto cols = parseColumns(rest);
    for (const auto& c : cols) {
        if (c != GRANT_OPTION_MARK) return false;
    }
    return true;
}

void StorageEngine::grant(const std::string& dbname, const std::string& tablename,
                          const std::string& username, TablePrivilege priv,
                          const std::vector<std::string>& columns,
                          bool withGrantOption,
                          const std::string& grantedBy) {
    auto ppath = permPath(dbname);
    std::map<std::string, std::set<std::string>> perms;
    if (std::filesystem::exists(ppath)) {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            auto key = permKey(u, t, p);
            if (!cols.empty()) {
                for (const auto& c : parseColumns(cols)) perms[key].insert(c);
            } else {
                perms[key] = {};
            }
        }
    }
    auto key = permKey(username, tablename, privToStr(priv));
    if (columns.empty()) {
        perms[key] = {};
    } else {
        if (perms[key].empty()) {
            auto it = perms.find(key);
            if (it != perms.end() && it->second.empty()) {
                it->second.clear();
            }
        }
        for (const auto& c : columns) perms[key].insert(c);
    }
    if (withGrantOption) {
        perms[key].insert(GRANT_OPTION_MARK);
    }
    std::ofstream ofs(ppath);
    for (const auto& kv : perms) {
        size_t p1 = kv.first.find('|');
        size_t p2 = kv.first.find('|', p1 + 1);
        std::string u = kv.first.substr(0, p1);
        std::string t = kv.first.substr(p1 + 1, p2 - p1 - 1);
        std::string p = kv.first.substr(p2 + 1);
        ofs << u << " " << t << " " << p;
        if (!kv.second.empty()) ofs << " " << joinColumns(std::vector<std::string>(kv.second.begin(), kv.second.end()));
        ofs << "\n";
    }
    // Record every explicit grant when the grantor is known.  PostgreSQL's
    // CASCADE semantics must be able to follow grants made without GRANT
    // OPTION as well: removing a grant option from the upstream grantor can
    // invalidate those downstream grants.
    if (!grantedBy.empty()) {
        auto gcp = grantChainPath(dbPath(dbname));
        bool exists = false;
        if (std::filesystem::exists(gcp)) {
            std::ifstream ifs(gcp);
            std::string line;
            while (std::getline(ifs, line)) {
                std::stringstream ss(line);
                std::string grantee, object, privilege, grantor;
                ss >> grantee >> object >> privilege >> grantor;
                if (grantee == username && object == tablename &&
                    privilege == privToStr(priv) && grantor == grantedBy) {
                    exists = true;
                    break;
                }
            }
        }
        if (!exists) {
            std::ofstream gcfs(gcp, std::ios::app);
            gcfs << username << " " << tablename << " " << privToStr(priv)
                 << " " << grantedBy << "\n";
        }
    }
}

bool StorageEngine::revoke(const std::string& dbname, const std::string& tablename,
                           const std::string& username, TablePrivilege priv,
                           const std::vector<std::string>& columns, bool cascade,
                           bool grantOptionOnly) {
    auto ppath = permPath(dbname);
    const auto gcp = grantChainPath(dbPath(dbname));
    std::vector<std::string> chainLines;
    if (std::filesystem::exists(gcp)) {
        std::ifstream ifs(gcp);
        std::string line;
        while (std::getline(ifs, line)) {
            if (!line.empty()) chainLines.push_back(line);
        }
    }
    std::vector<std::tuple<std::string, std::string, std::string>> downstream;
    for (const auto& line : chainLines) {
        std::stringstream ss(line);
        std::string grantee, object, privilege, grantor;
        ss >> grantee >> object >> privilege >> grantor;
        if (grantor == username && object == tablename &&
            privilege == privToStr(priv)) {
            downstream.emplace_back(grantee, object, privilege);
        }
    }
    if (!cascade && !downstream.empty()) return false;
    if (!std::filesystem::exists(ppath)) return true;
    std::map<std::string, std::set<std::string>> perms;
    {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            auto key = permKey(u, t, p);
            if (!cols.empty()) {
                for (const auto& c : parseColumns(cols)) perms[key].insert(c);
            } else {
                perms[key] = {};
            }
        }
    }
    auto key = permKey(username, tablename, privToStr(priv));
    auto it = perms.find(key);
    if (it != perms.end()) {
        if (columns.empty()) {
            if (grantOptionOnly) {
                it->second.erase(GRANT_OPTION_MARK);
                // An empty set is the canonical representation of a
                // table-level privilege, so keep it when the grant option
                // is removed from a table-level grant.  Column-scoped
                // grants with no remaining columns disappear.
                if (it->second.empty() && !columns.empty()) perms.erase(it);
            } else {
                perms.erase(it); // revoke entire privilege
            }
        } else {
            if (grantOptionOnly) {
                it->second.erase(GRANT_OPTION_MARK);
            } else {
                for (const auto& c : columns) it->second.erase(c);
            }
            if (it->second.empty()) perms.erase(it);
        }
    }
    {
        std::ofstream ofs(ppath);
        for (const auto& kv : perms) {
            size_t p1 = kv.first.find('|');
            size_t p2 = kv.first.find('|', p1 + 1);
            std::string u = kv.first.substr(0, p1);
            std::string t = kv.first.substr(p1 + 1, p2 - p1 - 1);
            std::string p = kv.first.substr(p2 + 1);
            ofs << u << " " << t << " " << p;
            if (!kv.second.empty()) ofs << " " << joinColumns(std::vector<std::string>(kv.second.begin(), kv.second.end()));
            ofs << "\n";
        }
    }

    // A fully revoked privilege no longer has a valid upstream grant chain.
    // Keep the chain when only GRANT OPTION is removed, because the base
    // privilege itself remains valid.
    if (!grantOptionOnly) {
        std::vector<std::string> remaining;
        for (const auto& line : chainLines) {
            std::stringstream ss(line);
            std::string grantee, object, privilege, grantor;
            ss >> grantee >> object >> privilege >> grantor;
            if (grantee == username && object == tablename &&
                privilege == privToStr(priv)) continue;
            remaining.push_back(line);
        }
        chainLines.swap(remaining);
    }

    if (!chainLines.empty()) {
        std::ofstream ofs(gcp);
        for (const auto& line : chainLines) ofs << line << "\n";
    } else if (std::filesystem::exists(gcp)) {
        std::error_code ec;
        std::filesystem::remove(gcp, ec);
    }

    // CASCADE: recursively revoke from users who received this privilege via the revoked user
    if (cascade) {
        std::vector<std::string> remaining;
        for (const auto& line : chainLines) {
            std::stringstream ss(line);
            std::string grantee, object, privilege, grantor;
            ss >> grantee >> object >> privilege >> grantor;
            if (grantor == username && object == tablename &&
                privilege == privToStr(priv)) continue;
            remaining.push_back(line);
        }
        chainLines.swap(remaining);
        for (const auto& ch : downstream) {
            revoke(dbname, std::get<1>(ch), std::get<0>(ch), priv, {}, true);
        }
    }
    return true;
}

bool StorageEngine::hasPermission(const std::string& dbname, const std::string& tablename,
                                  const std::string& username, TablePrivilege priv) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::ifstream ifs(ppath);
    std::string line;
    bool hasDbLevel = false;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p, cols;
        ss >> u >> t >> p;
        std::getline(ss, cols);
        if (!aclGranteeMatches(u, username)) continue;
        if (t == tablename && (p == "all" || p == target)) {
            if (colsEmptyIgnoreGrant(cols)) return true;
        }
        if (t == "*" && (p == "all" || p == target)) hasDbLevel = true;
    }
    return hasDbLevel;
}

bool StorageEngine::hasGrantOption(const std::string& dbname, const std::string& tablename,
                                   const std::string& username, TablePrivilege priv) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::ifstream ifs(ppath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p, cols;
        ss >> u >> t >> p;
        std::getline(ss, cols);
        if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
        if (!aclGranteeMatches(u, username)) continue;
        if (t != tablename && t != "*") continue;
        if (p == "all" || p == target) {
            auto colList = parseColumns(cols);
            for (const auto& c : colList) {
                if (c == GRANT_OPTION_MARK) return true;
            }
        }
    }
    return false;
}

bool StorageEngine::hasColumnPermission(const std::string& dbname, const std::string& tablename,
                                        const std::string& username, TablePrivilege priv,
                                        const std::vector<std::string>& columns) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    if (columns.empty()) return hasPermission(dbname, tablename, username, priv);
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::set<std::string> allowedCols;
    bool hasTableLevel = false;
    bool hasDbLevel = false;
    {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            if (!aclGranteeMatches(u, username)) continue;
            if (t == "*" && (p == "all" || p == target)) hasDbLevel = true;
            if (t != tablename) continue;
            if (p == "all") hasTableLevel = true;
            if (p == target) {
                if (cols.empty()) hasTableLevel = true;
                else {
                    bool hasGrantMarker = false;
                    bool hasColumn = false;
                    for (const auto& c : parseColumns(cols)) {
                        if (c == GRANT_OPTION_MARK) hasGrantMarker = true;
                        else {
                            hasColumn = true;
                            allowedCols.insert(c);
                        }
                    }
                    // A table-level grant with GRANT OPTION is serialized as
                    // the marker alone and still applies to every column.
                    if (hasGrantMarker && !hasColumn) hasTableLevel = true;
                }
            }
        }
    }
    if (hasTableLevel || hasDbLevel) return true;
    for (const auto& col : columns) {
        if (allowedCols.find(col) == allowedCols.end()) return false;
    }
    return true;
}

std::vector<std::string> StorageEngine::getUserPermissions(
    const std::string& dbname, const std::string& tablename,
    const std::string& username) const {
    std::vector<std::string> result;
    if (tableOwnerMatches(*this, dbname, tablename, username)) {
        result.push_back("all");
        return result;
    }
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return result;
    std::ifstream ifs(ppath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p;
        ss >> u >> t >> p;
        if (t == tablename && aclGranteeMatches(u, username)) result.push_back(p);
    }
    return result;
}

